option.value:
'use client';

import { useState, useMemo, memo, Suspense, lazy } from 'react';
import Link from 'next/link';
import { runSimulation, TeamPerformanceDistribution, SimulatedMatch } from '@/lib/simulation';
import { calculateTeamEPA, ScoutReport } from '@/lib/spr';
import { StatboticsTeamEvent } from '@/lib/statbotics';
import { predictUpcomingMatches } from '@/lib/predictions';
import { exportToCSV, ExportableTeam } from '@/lib/export';


interface TbaMatchLite {
    key?: string;
    matchKey?: string;
    match_number?: number;
    alliances?: {
        red: { score: number; team_keys: string[] };
        blue: { score: number; team_keys: string[] };
    };
    score_breakdown?: {
        red?: { rp?: number };
        blue?: { rp?: number };
    };
}

interface RankingsLite {
    rankings?: Array<{ team_key: string; rank: number }>;
}

type ReportWithMatchNum = ScoutReport & { matchNum: number };

interface EventDashboardProps {
    eventKey: string;
    reports: ScoutReport[];
    schedule: SimulatedMatch[];
    distributions: TeamPerformanceDistribution[];
    teamNameMap: Record<string, string>;
    aiSummary: string;
    tbaMatchesRaw: TbaMatchLite[];
    actualRankings: RankingsLite | null;
    statboticsData: StatboticsTeamEvent[];
}

export default function EventDashboard({ eventKey, reports, schedule, distributions, teamNameMap, aiSummary, tbaMatchesRaw, actualRankings, statboticsData }: EventDashboardProps) {
    void aiSummary;
    void actualRankings;

    const parsedReports = useMemo<ReportWithMatchNum[]>(() => {
        return reports.map((r) => ({
            ...r,
            matchNum: parseInt((r.matchKey || '').split('_qm').pop() || '0', 10),
        }));
    }, [reports]);

    const reportsByTeam = useMemo(() => {
        const map = new Map<string, ReportWithMatchNum[]>();
        parsedReports.forEach((report) => {
            const existing = map.get(report.teamKey);
            if (existing) existing.push(report);
            else map.set(report.teamKey, [report]);
        });
        return map;
    }, [parsedReports]);

    const statboticsByTeamNum = useMemo(() => {
        const map = new Map<number, StatboticsTeamEvent>();
        statboticsData.forEach((row) => map.set(row.team, row));
        return map;
    }, [statboticsData]);

    const maxMatch = useMemo(() => {
        const nums = schedule.map(m => parseInt(m.matchKey.split('_qm').pop() || '0'));
        return Math.max(...nums, 0);
    }, [schedule]);

    // Default to the highest match we actually have scouting data for,
    // so the countdown always points at real upcoming matches.
    const lastScoutedMatch = useMemo(() => {
        if (parsedReports.length === 0) return 0;
        return Math.max(...parsedReports.map(r => r.matchNum), 0);
    }, [parsedReports]);

    const [matchLimit, setMatchLimit] = useState(() => lastScoutedMatch);

    // 1. Calculate Ground Truth RPs (from TBA) up to matchLimit
    const groundTruthRPs = useMemo(() => {
        const rps: Record<string, number> = {};
        tbaMatchesRaw.forEach(m => {
            const mNum = parseInt(m.matchKey?.split('_qm').pop() || m.match_number?.toString() || '0');
            if (mNum <= matchLimit && m.alliances) {
                let redRPs = 0;
                let blueRPs = 0;

                if (m.score_breakdown) {
                    redRPs = m.score_breakdown.red?.rp || 0;
                    blueRPs = m.score_breakdown.blue?.rp || 0;
                } else {
                    const redScore = m.alliances.red.score;
                    const blueScore = m.alliances.blue.score;
                    redRPs = redScore > blueScore ? 2 : redScore === blueScore ? 1 : 0;
                    blueRPs = blueScore > redScore ? 2 : blueScore === redScore ? 1 : 0;
                }

                m.alliances.red.team_keys.forEach((t: string) => rps[t] = (rps[t] || 0) + redRPs);
                m.alliances.blue.team_keys.forEach((t: string) => rps[t] = (rps[t] || 0) + blueRPs);
            }
        });
        return rps;
    }, [tbaMatchesRaw, matchLimit]);

    // 2. Filter distributions based on matchLimit (Time-travel)
    const filteredDistributions = useMemo(() => {
        return distributions.map(d => {
            const teamReports = reportsByTeam.get(d.teamKey) ?? [];
            return {
                ...d,
                pastSyntheticMatches: teamReports
                    .filter(r => r.matchNum <= matchLimit)
                    .map(r => r.data),
            };
        });
    }, [distributions, reportsByTeam, matchLimit]);

    // 2.5 Calculate Historical Rank Map (TBA Rank at Match Limit)
    const historicalRankMap = useMemo(() => {
        const sorted = Object.entries(groundTruthRPs)
            .sort((a, b) => b[1] - a[1])
            .map(([teamKey]) => teamKey);

        const map: Record<string, number> = {};
        sorted.forEach((teamKey, index) => {
            map[teamKey] = index + 1;
        });
        return map;
    }, [groundTruthRPs]);

    // 3. Run Simulation (starting from Ground Truth RPs)
    const results = useMemo(() => {
        return runSimulation(filteredDistributions, schedule, groundTruthRPs, matchLimit);
    }, [filteredDistributions, schedule, groundTruthRPs, matchLimit]);

    const resultsByTeam = useMemo(() => {
        const map = new Map<string, (typeof results)[number]>();
        results.forEach((row) => map.set(row.teamKey, row));
        return map;
    }, [results]);

    const topTeams = [...results].sort((a, b) => {
        const rA = historicalRankMap[a.teamKey] || 999;
        const rB = historicalRankMap[b.teamKey] || 999;
        return rA - rB;
    }).slice(0, 15).map((r) => {
        const teamNum = parseInt(r.teamKey.replace('frc', ''), 10);
        const sbData = statboticsByTeamNum.get(teamNum);
        const teamReports = (reportsByTeam.get(r.teamKey) ?? []).filter(rep => rep.matchNum <= matchLimit);
        const ourEPA = calculateTeamEPA(teamReports).toFixed(1);

        const simResult = resultsByTeam.get(r.teamKey);
        const top8Count = simResult
            ? Object.entries(simResult.rankDistribution)
                .filter(([rank]) => parseInt(rank, 10) <= 8)
                .reduce((acc, [, cnt]) => acc + cnt, 0)
            : 0;
        const top8Prob = (top8Count / 10000 * 100).toFixed(0);
        const simExpectedRank = simResult ? Math.round(simResult.expectedRank) : 999;

        return {
            teamKey: r.teamKey,
            team: r.teamKey.replace('frc', ''),
            name: teamNameMap[r.teamKey] || 'UNIT',
            expected: simExpectedRank,
            actual: historicalRankMap[r.teamKey] || '?',
            prob: `${top8Prob}%`,
            rp: r.avgRP.toFixed(1),
            ourEPA,
            sbEPA: sbData?.epa?.breakdown?.total_points?.toFixed(1) || 'N/A'
        };
    });

    // 4. Generate Match Predictions for upcoming matches
    const matchPredictions = useMemo(() => {
        return predictUpcomingMatches(schedule, filteredDistributions, matchLimit);
    }, [schedule, filteredDistributions, matchLimit]);

    const matchPredictionMap = useMemo(() => {
        const map: Record<string, (typeof matchPredictions)[number]> = {};
        matchPredictions.forEach((prediction) => {
            map[prediction.matchKey] = prediction;
        });
        return map;
    }, [matchPredictions]);

    // 5. Build a quick lookup for played match results (score + winner)
    const playedResultsMap = useMemo(() => {
        const map: Record<string, { redScore: number; blueScore: number; winner: 'red' | 'blue' | 'tie' }> = {};
        tbaMatchesRaw.forEach((m) => {
            const key = m.key ?? m.matchKey;
            if (!key || !m.alliances) return;
            const redScore: number = m.alliances.red?.score ?? -1;
            const blueScore: number = m.alliances.blue?.score ?? -1;
            if (redScore < 0 || blueScore < 0) return;
            map[key] = {
                redScore,
                blueScore,
                winner: redScore > blueScore ? 'red' : blueScore > redScore ? 'blue' : 'tie',
            };
        });
        return map;
    }, [tbaMatchesRaw]);

    const epaCards = useMemo(() => {
        return Array.from(reportsByTeam.entries())
            .map(([teamKey, teamReports]) => {
                const teamNum = parseInt(teamKey.replace('frc', ''), 10);
                const ourEPAValue = calculateTeamEPA(teamReports);
                const ourEPA = ourEPAValue.toFixed(1);

                const sbData = statboticsByTeamNum.get(teamNum);
                const sbPoints = sbData?.epa?.breakdown?.total_points;
                const sbEPA = sbPoints != null ? sbPoints.toFixed(1) : 'N/A';

                const diffValue = sbPoints != null ? ourEPAValue - sbPoints : 0;
                const diff = diffValue.toFixed(1);
                const diffColor = diffValue > 0 ? '#22c55e' : diffValue < 0 ? '#ef4444' : '#888';

                return {
                    teamKey,
                    teamNum,
                    name: teamNameMap[teamKey] || 'TEAM',
                    ourEPA,
                    ourEPAValue,
                    sbEPA,
                    diff,
                    diffColor,
                };
            })
            .sort((a, b) => b.ourEPAValue - a.ourEPAValue);
    }, [reportsByTeam, statboticsByTeamNum, teamNameMap]);

    return (
        <main style={{ minHeight: '100vh', background: 'var(--background)', color: 'var(--foreground)', padding: 'clamp(5.5rem, 8vw, 2.5rem) clamp(1rem, 4vw, 1.25rem) 2rem', overflow: 'hidden' }}>
            <div className="mx-auto responsive-padding" style={{ maxWidth: '1200px', display: 'grid', gap: '2rem', width: '100%' }}>

                <header className="flex flex-col md:flex-row justify-between items-start md:items-end reveal mobile-stack" style={{ gap: '1.5rem' }}>
                    <div style={{ display: 'grid', gap: '0.6rem' }}>
                        <div className="flex items-center" style={{ gap: '0.75rem' }}>
                            <div style={{ width: '8px', height: '8px', borderRadius: '50%', background: 'var(--primary-teal)', boxShadow: '0 0 12px var(--primary-teal)' }}></div>
                            <p style={{ fontSize: '11px', fontWeight: 950, letterSpacing: '0.2em', textTransform: 'uppercase', color: 'var(--primary-teal)' }}>⚙ {eventKey.split('2026')[1]?.toUpperCase() || eventKey.toUpperCase()} DASHBOARD</p>
                        </div>
                        <h1 style={{ fontSize: 'clamp(2.8rem, 10vw, 5.5rem)', fontWeight: 950, letterSpacing: '-0.03em', lineHeight: 1, background: 'linear-gradient(135deg, var(--primary-teal) 0%, var(--primary-brown) 100%)', backgroundClip: 'text', WebkitBackgroundClip: 'text', color: 'transparent' }}>
                            {eventKey.toUpperCase()}
                        </h1>
                        <p style={{ color: 'var(--muted)', fontSize: '1rem', fontWeight: 500 }}>Match simulation and point-in-time ranking view</p>
                    </div>

                    <div className="w-full md:w-auto event-header-actions" style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', justifyContent: 'center' }}>
                        <Link href={`/event/${eventKey}/teams`} style={{ textDecoration: 'none', flex: '1 1 auto', minWidth: '90px', maxWidth: '150px' }}>
                            <div className="glass" style={{ padding: '0.65rem 0.85rem', borderRadius: '999px', border: '1px solid rgba(255,255,255,0.16)', background: 'rgba(255, 255, 255, 0.03)', textAlign: 'center', whiteSpace: 'nowrap' }}>
                                <p style={{ fontSize: '9px', fontWeight: 650, color: 'var(--foreground)', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                    Teams
                                </p>
                            </div>
                        </Link>
                        <Link href={`/scouters/${eventKey}`} style={{ textDecoration: 'none', flex: '1 1 auto', minWidth: '100px', maxWidth: '150px' }}>
                            <div className="glass" style={{ padding: '0.65rem 0.85rem', borderRadius: '999px', border: '1px solid rgba(124,109,216,0.35)', background: 'rgba(124,109,216,0.08)', textAlign: 'center', whiteSpace: 'nowrap' }}>
                                <p style={{ fontSize: '9px', fontWeight: 650, color: 'var(--primary)', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                    Scouter Intel
                                </p>
                            </div>
                        </Link>
                        <Link href={`/event/${eventKey}/draft`} style={{ textDecoration: 'none', flex: '1 1 auto', minWidth: '95px', maxWidth: '150px' }}>
                            <div className="glass" style={{ padding: '0.65rem 0.85rem', borderRadius: '999px', border: '1px solid rgba(79,174,192,0.35)', background: 'rgba(79,174,192,0.08)', textAlign: 'center', whiteSpace: 'nowrap' }}>
                                <p style={{ fontSize: '9px', fontWeight: 650, color: 'var(--secondary)', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                    Draft Advisor
                                </p>
                            </div>
                        </Link>
                        <Link href={`/event/${eventKey}/alliance-sim`} style={{ textDecoration: 'none', flex: '1 1 auto', minWidth: '105px', maxWidth: '150px' }}>
                            <div className="glass" style={{ padding: '0.65rem 0.85rem', borderRadius: '999px', border: '1px solid rgba(99,143,209,0.35)', background: 'rgba(99,143,209,0.08)', textAlign: 'center', whiteSpace: 'nowrap' }}>
                                <p style={{ fontSize: '9px', fontWeight: 650, color: '#76a8df', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                    Alliance Sim
                                </p>
                            </div>
                        </Link>
                        <Link href={`/event/${eventKey}/compare`} style={{ textDecoration: 'none', flex: 1 }}>
                            <div className="glass" style={{ padding: '0.75rem 1rem', borderRadius: '999px', border: '1px solid rgba(213,182,90,0.35)', background: 'rgba(213,182,90,0.08)', textAlign: 'center' }}>
                                <p style={{ fontSize: '10px', fontWeight: 650, color: '#d5b65a' }}>
                                    Compare
                                </p>
                            </div>
                        </Link>
                        <Link href="/quick-scout" style={{ textDecoration: 'none', flex: 1 }}>
                            <div className="glass" style={{ padding: '0.75rem 1rem', borderRadius: '999px', border: '1px solid rgba(205,93,116,0.35)', background: 'rgba(205,93,116,0.08)', textAlign: 'center' }}>
                                <p style={{ fontSize: '10px', fontWeight: 650, color: 'var(--accent)' }}>
                                    Quick Scout
                                </p>
                            </div>
                        </Link>
                        <Link href={`/event/${eventKey}/anomalies`} style={{ textDecoration: 'none', flex: 1 }}>
                            <div className="glass" style={{ padding: '0.75rem 1rem', borderRadius: '999px', border: '1px solid rgba(172,36,36,0.35)', background: 'rgba(172,36,36,0.08)', textAlign: 'center' }}>
                                <p style={{ fontSize: '10px', fontWeight: 650, color: 'var(--secondary-red)' }}>
                                    Anomalies
                                </p>
                            </div>
                        </Link>
                    </div>
                </header>


                {/* Simulation Control (Slider) */}
                <section className="reveal delay-2">
                    <div className="glass" style={{ padding: '1.4rem', borderRadius: '24px' }}>
                        <div className="flex justify-between items-center mobile-stack" style={{ marginBottom: '1rem' }}>
                            <h3 style={{ fontSize: '10px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: '0.1em' }}>Point-in-Time Analysis</h3>
                            <span style={{ fontSize: 'clamp(1.1rem, 4vw, 1.4rem)', fontWeight: 760, color: 'var(--primary)' }}>Up to Match {matchLimit}</span>
                        </div>
                        <input
                            type="range" min="0" max={maxMatch} value={matchLimit}
                            onChange={(e) => setMatchLimit(parseInt(e.target.value))}
                            style={{ width: '100%', height: '8px', borderRadius: '10px', background: 'rgba(255,255,255,0.05)', accentColor: 'var(--primary)', cursor: 'pointer' }}
                        />
                        <div className="flex justify-between" style={{ marginTop: '0.5rem' }}>
                            <span style={{ fontSize: '9px', fontWeight: 650, color: 'var(--muted)' }}>Pre-event</span>
                            <span style={{ fontSize: '9px', fontWeight: 650, color: 'var(--muted)' }}>Current</span>
                        </div>
                    </div>
                </section>

                {/* Main Body Grid */}
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '1rem' }}>

                    {/* Left: Leaderboard */}
                    <div style={{ gridColumn: 'span min(3, 4)', display: 'grid', gap: '2rem' }} className="reveal delay-3">
                        <div className="flex justify-between items-center" style={{ paddingBottom: '0.8rem', borderBottom: '1px solid rgba(255,255,255,0.08)' }}>
                            <div className="flex items-center gap-4">
                                <h2 style={{ fontSize: '11px', fontWeight: 700, letterSpacing: '0.08em', textTransform: 'uppercase', color: 'var(--muted)' }}>TBA Rankings (Match {matchLimit})</h2>
                                <button
                                    onClick={() => {
                                        const exportData: ExportableTeam[] = topTeams.map((t, index) => ({
                                            rank: index + 1,
                                            teamNumber: t.team,
                                            teamName: t.name,
                                            ourEPA: parseFloat(t.ourEPA),
                                            sbEPA: t.sbEPA === 'N/A' ? null : parseFloat(t.sbEPA),
                                            failureRate: 0, // Placeholder
                                            consistencyScore: 50, // Placeholder
                                            notes: ""
                                        }));
                                        exportToCSV(exportData, `${eventKey}_rankings`);
                                    }}
                                    className="glass-button"
                                    style={{
                                        padding: '0.4rem 0.8rem',
                                        fontSize: '9px',
                                        fontWeight: 950,
                                        color: 'var(--primary)',
                                        borderRadius: '10px',
                                        border: '1px solid rgba(124,109,216,0.5)',
                                        background: 'rgba(124,109,216,0.08)',
                                        cursor: 'pointer',
                                        textTransform: 'uppercase'
                                    }}
                                >
                                    Export CSV
                                </button>
                            </div>
                            <span style={{ fontSize: '9px', fontWeight: 650, color: 'var(--muted)' }}>Samples: {filteredDistributions.reduce((acc, d) => acc + d.pastSyntheticMatches.length, 0)}</span>
                        </div>

                        <div style={{ display: 'grid', gap: '0.85rem' }}>
                            {topTeams.map((p) => (
                                <Link key={p.teamKey} href={`/event/${eventKey}/team/${p.teamKey}`} style={{ textDecoration: 'none', color: 'inherit' }}>
                                    <div className="glass flex items-center leaderboard-card" style={{ padding: '1.2rem', gap: '1.25rem', borderRadius: '22px', border: '1px solid rgba(255,255,255,0.08)' }}>
                                        <div className="flex items-center gap-8 rank-pill">
                                            <div style={{ textAlign: 'center' }}>
                                                <p style={{ fontSize: '10px', fontWeight: 700, color: 'var(--primary)', textTransform: 'uppercase', letterSpacing: '0.06em' }}>TBA</p>
                                                <span style={{ fontSize: '2.2rem', fontWeight: 760, color: 'var(--foreground)' }}>#{p.actual}</span>
                                            </div>
                                            <div className="rank-divider" style={{ width: '1px', height: '2.3rem', background: 'rgba(255,255,255,0.12)' }}></div>
                                            <div style={{ textAlign: 'center' }}>
                                                <p style={{ fontSize: '10px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: '0.06em' }}>SIM</p>
                                                <span style={{ fontSize: '1.8rem', fontWeight: 760, color: p.actual === p.expected ? 'var(--secondary)' : 'var(--muted)' }}>#{p.expected}</span>
                                            </div>
                                        </div>

                                        <div style={{ flex: 1 }}>
                                            <p style={{ fontSize: '11px', fontWeight: 700, color: 'var(--primary)', letterSpacing: '0.06em' }}>Team {p.team}</p>
                                            <h3 style={{ fontSize: 'clamp(1.1rem, 3vw, 1.5rem)', fontWeight: 720, color: 'var(--foreground)', lineHeight: 1.1 }}>{p.name}</h3>
                                        </div>

                                        <div className="flex items-center gap-8 mobile-stack">
                                            <div>
                                                <p style={{ fontSize: '10px', fontWeight: 700, color: 'var(--primary)', textTransform: 'uppercase' }}>Our EPA</p>
                                                <p style={{ fontSize: 'clamp(1.05rem, 3vw, 1.35rem)', fontWeight: 760, color: 'var(--foreground)', fontFamily: 'monospace' }}>{p.ourEPA}</p>
                                            </div>
                                            <div className="rank-divider" style={{ width: '1px', height: '2.2rem', background: 'rgba(255,255,255,0.12)' }}></div>
                                            <div>
                                                <p style={{ fontSize: '10px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase' }}>SB EPA</p>
                                                <p style={{ fontSize: 'clamp(1.05rem, 3vw, 1.35rem)', fontWeight: 700, color: '#d0d5de', fontFamily: 'monospace' }}>{p.sbEPA}</p>
                                            </div>
                                            <div className="rank-divider" style={{ width: '1px', height: '2.2rem', background: 'rgba(255,255,255,0.12)' }}></div>
                                            <div style={{ textAlign: 'right' }}>
                                                <p style={{ fontSize: '10px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase' }}>Top 8</p>
                                                <div style={{ fontSize: 'clamp(1.1rem, 3vw, 1.5rem)', fontWeight: 760, color: 'var(--secondary)' }}>
                                                    {p.prob}
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>

                    {/* Right: Insights */}
                    <div style={{ display: 'grid', gap: '2rem' }} className="reveal delay-4">
                        <section className="glass" style={{ padding: '1.4rem', borderRadius: '22px' }}>
                            <h3 style={{ fontSize: '10px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '1rem' }}>Simulation Health</h3>
                            <p style={{ fontSize: '0.86rem', color: '#c7ced7', lineHeight: 1.5, marginBottom: '1rem' }}>
                                {matchLimit === 0
                                    ? "Pre-event baseline. Based on generic synthetic samples."
                                    : `Point-in-time snapshot using real data up to Match ${matchLimit}.`}
                            </p>
                            <div style={{ height: '4px', background: 'rgba(255,255,255,0.06)', borderRadius: '10px' }}>
                                <div style={{ height: '100%', borderRadius: '10px', background: '#84caa7', width: `${Math.min(100, (matchLimit / maxMatch) * 100)}%` }}></div>
                            </div>
                        </section>
                    </div>
                </div>

                {/* Tactical Schedule */}
                <div className="reveal delay-5" style={{ marginTop: '1rem' }}>
                    <div className="flex justify-between items-end" style={{ marginBottom: '1.5rem' }}>
                        <div>
                            <h2 style={{ fontSize: '1.25rem', fontWeight: 760, marginBottom: '0.5rem' }}>Match Schedule</h2>
                            <p style={{ fontSize: '11px', color: 'var(--muted)', fontWeight: 600 }}>Per-match score and win probability view</p>
                        </div>
                    </div>

                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '1rem' }}>
                        {schedule.map((m: SimulatedMatch) => {
                            const mNum = parseInt(m.matchKey.split('_qm').pop() || '0');
                            const isPlayed = mNum <= matchLimit;
                            const result = playedResultsMap[m.matchKey];
                            return (
                                <Link key={m.matchKey} href={`/match/${m.matchKey}`} style={{ textDecoration: 'none', opacity: isPlayed ? 0.75 : 1 }}>
                                    <div className="glass" style={{ padding: '1rem', borderRadius: '18px', border: isPlayed ? '1px solid rgba(255,255,255,0.06)' : '1px solid rgba(255,255,255,0.1)' }}>
                                        <div className="flex justify-between items-center" style={{ marginBottom: '0.8rem' }}>
                                            <span style={{ fontSize: '11px', fontWeight: 700, color: isPlayed ? 'var(--muted)' : 'var(--primary)' }}>{m.matchKey.split('_').pop()?.toUpperCase() || 'QM?'}</span>
                                            {isPlayed && result ? (
                                                <span style={{
                                                    fontSize: '9px', fontWeight: 700, textTransform: 'uppercase',
                                                    color: result.winner === 'tie' ? '#d5b65a' : result.winner === 'red' ? '#cd5d74' : '#76a8df'
                                                }}>
                                                    {result.winner === 'tie' ? '⚖ TIE' : result.winner === 'red' ? ' RED WIN' : ' BLUE WIN'}
                                                </span>
                                            ) : isPlayed ? (
                                                <span style={{ fontSize: '9px', fontWeight: 700, color: '#84caa7' }}>Complete</span>
                                            ) : (
                                                <span style={{ fontSize: '9px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase' }}>Preview</span>
                                            )}
                                        </div>
                                        <div style={{ display: 'grid', gap: '0.75rem' }}>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '0.5rem', background: isPlayed && result?.winner === 'red' ? 'rgba(205,93,116,0.14)' : 'rgba(205,93,116,0.08)', padding: '0.5rem', borderRadius: '10px' }}>
                                                <div style={{ display: 'flex', gap: '0.5rem' }}>
                                                    {m.red.map((t: string) => <span key={t} style={{ color: '#cd5d74', fontSize: '12px', fontWeight: 700 }}>{t.replace('frc', '')}</span>)}
                                                </div>
                                                {result && <span style={{ fontSize: '1rem', fontWeight: 760, color: result.winner === 'red' ? '#cd5d74' : 'var(--muted)', fontFamily: 'monospace' }}>{result.redScore}</span>}
                                            </div>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '0.5rem', background: isPlayed && result?.winner === 'blue' ? 'rgba(118,168,223,0.14)' : 'rgba(118,168,223,0.08)', padding: '0.5rem', borderRadius: '10px' }}>
                                                <div style={{ display: 'flex', gap: '0.5rem' }}>
                                                    {m.blue.map((t: string) => <span key={t} style={{ color: '#76a8df', fontSize: '12px', fontWeight: 700 }}>{t.replace('frc', '')}</span>)}
                                                </div>
                                                {result && <span style={{ fontSize: '1rem', fontWeight: 760, color: result.winner === 'blue' ? '#76a8df' : 'var(--muted)', fontFamily: 'monospace' }}>{result.blueScore}</span>}
                                            </div>
                                            {!isPlayed && (() => {
                                                const prediction = matchPredictionMap[m.matchKey];
                                                if (!prediction) return null;
                                                const confColor = prediction.confidence === 'high' ? '#22c55e' : prediction.confidence === 'medium' ? '#eab308' : '#ef4444';
                                                return (
                                                    <div style={{ marginTop: '0.45rem', padding: '0.65rem', background: 'rgba(255,255,255,0.02)', borderRadius: '10px', borderLeft: `2px solid ${confColor}` }}>
                                                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem' }}>
                                                            <span style={{ fontSize: '9px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase' }}>Win Probability</span>
                                                            <span style={{ fontSize: '9px', fontWeight: 700, color: confColor, textTransform: 'uppercase' }}>{prediction.confidence}</span>
                                                        </div>
                                                        <div style={{ display: 'grid', gridTemplateColumns: '1fr auto 1fr', gap: '0.5rem', alignItems: 'center' }}>
                                                            <div style={{ textAlign: 'center' }}>
                                                                <div style={{ fontSize: '1.1rem', fontWeight: 760, color: '#cd5d74' }}>{(prediction.redWinProbability * 100).toFixed(0)}%</div>
                                                                <div style={{ fontSize: '9px', color: 'var(--muted)' }}>{prediction.redScoreRange.mean.toFixed(0)} pts</div>
                                                            </div>
                                                            <div style={{ fontSize: '10px', color: 'var(--muted)' }}>vs</div>
                                                            <div style={{ textAlign: 'center' }}>
                                                                <div style={{ fontSize: '1.1rem', fontWeight: 760, color: '#76a8df' }}>{(prediction.blueWinProbability * 100).toFixed(0)}%</div>
                                                                <div style={{ fontSize: '9px', color: 'var(--muted)' }}>{prediction.blueScoreRange.mean.toFixed(0)} pts</div>
                                                            </div>
                                                        </div>
                                                    </div>
                                                );
                                            })()}
                                            {isPlayed && result && (() => {
                                                const prediction = matchPredictionMap[m.matchKey];
                                                if (!prediction) return null;
                                                const predictedWinner = prediction.redWinProbability >= prediction.blueWinProbability ? 'red' : 'blue';
                                                const correct = predictedWinner === result.winner || result.winner === 'tie';
                                                return (
                                                    <div style={{ padding: '0.5rem 0.75rem', background: 'rgba(255,255,255,0.02)', borderRadius: '8px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                                        <span style={{ fontSize: '9px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase' }}>Predicted</span>
                                                        <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'center' }}>
                                                            <span style={{ fontSize: '9px', fontWeight: 700, color: '#cd5d74' }}>{(prediction.redWinProbability * 100).toFixed(0)}%R</span>
                                                            <span style={{ fontSize: '9px', color: 'var(--muted)' }}>·</span>
                                                            <span style={{ fontSize: '9px', fontWeight: 700, color: '#76a8df' }}>{(prediction.blueWinProbability * 100).toFixed(0)}%B</span>
                                                            <span style={{ fontSize: '9px', fontWeight: 700, color: correct ? '#84caa7' : '#cd5d74' }}>{correct ? '✓' : '✗'}</span>
                                                        </div>
                                                    </div>
                                                );
                                            })()}
                                        </div>
                                    </div>
                                </Link>
                            );
                        })}
                    </div>
                </div>

                {/* EPA Analysis Section */}
                <div className="reveal delay-6" style={{ marginTop: '1rem' }}>
                    <h2 style={{ fontSize: '1.2rem', fontWeight: 760, marginBottom: '1rem' }}>EPA Analysis (Our Data vs Statbotics)</h2>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '0.85rem' }}>
                        {epaCards.map((card) => (
                            <div key={card.teamKey} className="glass" style={{ padding: '1.15rem', borderRadius: '16px', border: '1px solid rgba(255,255,255,0.08)' }}>
                                <div className="flex justify-between items-center" style={{ marginBottom: '0.8rem' }}>
                                    <span style={{ fontSize: '1.1rem', fontWeight: 760, color: 'var(--primary)' }}>{card.teamNum}</span>
                                    <span style={{ fontSize: '0.72rem', fontWeight: 600, color: 'var(--muted)' }}>{card.name}</span>
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <p style={{ fontSize: '9px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase' }}>Our EPA</p>
                                        <p style={{ fontSize: '1.3rem', fontWeight: 760, color: 'var(--foreground)' }}>{card.ourEPA}</p>
                                    </div>
                                    <div>
                                        <p style={{ fontSize: '9px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase' }}>Statbotics</p>
                                        <p style={{ fontSize: '1.3rem', fontWeight: 700, color: '#d0d5de' }}>{card.sbEPA}</p>
                                    </div>
                                </div>

                                <div style={{ marginTop: '0.8rem', paddingTop: '0.8rem', borderTop: '1px solid rgba(255,255,255,0.08)' }}>
                                    <p style={{ fontSize: '9px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase' }}>Difference</p>
                                    <p style={{ fontSize: '1rem', fontWeight: 760, color: card.diffColor }}>{parseFloat(card.diff) > 0 ? '+' : ''}{card.diff}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

            </div >
        </main >
    );
}

'use client';

import { useState, useMemo, memo, Suspense, lazy } from 'react';
import Link from 'next/link';
import { runSimulation, TeamPerformanceDistribution, SimulatedMatch } from '@/lib/simulation';
import { calculateTeamEPA } from '@/lib/spr';
import { ScoutReport } from '@/lib/types/scouting';
import { StatboticsTeamEvent } from '@/lib/statbotics';
import { predictUpcomingMatches } from '@/lib/predictions';
import { exportToCSV, ExportableTeam } from '@/lib/export';


interface TbaMatchLite {
    key?: string;
    matchKey?: string;
    match_number?: number;
    alliances?: {
        red: { score: number; team_keys: string[] };
        blue: { score: number; team_keys: string[] };
    };
    score_breakdown?: {
        red?: { rp?: number };
        blue?: { rp?: number };
    };
}

interface RankingsLite {
    rankings?: Array<{ team_key: string; rank: number }>;
}

type ReportWithMatchNum = ScoutReport & { matchNum: number };

interface EventDashboardProps {
    eventKey: string;
    reports: ScoutReport[];
    schedule: SimulatedMatch[];
    distributions: TeamPerformanceDistribution[];
    teamNameMap: Record<string, string>;
    aiSummary: string;
    tbaMatchesRaw: TbaMatchLite[];
    actualRankings: RankingsLite | null;
    statboticsData: StatboticsTeamEvent[];
}

export default function EventDashboard({ eventKey, reports, schedule, distributions, teamNameMap, aiSummary, tbaMatchesRaw, actualRankings, statboticsData }: EventDashboardProps) {
    void aiSummary;
    void actualRankings;

    const parsedReports = useMemo<ReportWithMatchNum[]>(() => {
        return reports.map((r) => ({
            ...r,
            matchNum: parseInt((r.matchKey || '').split('_qm').pop() || '0', 10),
        }));
    }, [reports]);

    const reportsByTeam = useMemo(() => {
        const map = new Map<string, ReportWithMatchNum[]>();
        parsedReports.forEach((report) => {
            const existing = map.get(report.teamKey);
            if (existing) existing.push(report);
            else map.set(report.teamKey, [report]);
        });
        return map;
    }, [parsedReports]);

    const statboticsByTeamNum = useMemo(() => {
        const map = new Map<number, StatboticsTeamEvent>();
        statboticsData.forEach((row) => map.set(row.team, row));
        return map;
    }, [statboticsData]);

    const maxMatch = useMemo(() => {
        const nums = schedule.map(m => parseInt(m.matchKey.split('_qm').pop() || '0'));
        return Math.max(...nums, 0);
    }, [schedule]);

    // Default to the highest match we actually have scouting data for,
    // so the countdown always points at real upcoming matches.
    const lastScoutedMatch = useMemo(() => {
        if (parsedReports.length === 0) return 0;
        return Math.max(...parsedReports.map(r => r.matchNum), 0);
    }, [parsedReports]);

    const [matchLimit, setMatchLimit] = useState(() => lastScoutedMatch);

    // 1. Calculate Ground Truth RPs (from TBA) up to matchLimit
    const groundTruthRPs = useMemo(() => {
        const rps: Record<string, number> = {};
        tbaMatchesRaw.forEach(m => {
            const mNum = parseInt(m.matchKey?.split('_qm').pop() || m.match_number?.toString() || '0');
            if (mNum <= matchLimit && m.alliances) {
                let redRPs = 0;
                let blueRPs = 0;

                if (m.score_breakdown) {
                    redRPs = m.score_breakdown.red?.rp || 0;
                    blueRPs = m.score_breakdown.blue?.rp || 0;
                } else {
                    const redScore = m.alliances.red.score;
                    const blueScore = m.alliances.blue.score;
                    redRPs = redScore > blueScore ? 2 : redScore === blueScore ? 1 : 0;
                    blueRPs = blueScore > redScore ? 2 : blueScore === redScore ? 1 : 0;
                }

                m.alliances.red.team_keys.forEach((t: string) => rps[t] = (rps[t] || 0) + redRPs);
                m.alliances.blue.team_keys.forEach((t: string) => rps[t] = (rps[t] || 0) + blueRPs);
            }
        });
        return rps;
    }, [tbaMatchesRaw, matchLimit]);

    // 2. Filter distributions based on matchLimit (Time-travel)
    const filteredDistributions = useMemo(() => {
        return distributions.map(d => {
            const teamReports = reportsByTeam.get(d.teamKey) ?? [];
            return {
                ...d,
                pastSyntheticMatches: teamReports
                    .filter(r => r.matchNum <= matchLimit)
                    .map(r => r.data),
            };
        });
    }, [distributions, reportsByTeam, matchLimit]);

    // 2.5 Calculate Historical Rank Map (TBA Rank at Match Limit)
    const historicalRankMap = useMemo(() => {
        const sorted = Object.entries(groundTruthRPs)
            .sort((a, b) => b[1] - a[1])
            .map(([teamKey]) => teamKey);

        const map: Record<string, number> = {};
        sorted.forEach((teamKey, index) => {
            map[teamKey] = index + 1;
        });
        return map;
    }, [groundTruthRPs]);

    // 3. Run Simulation (starting from Ground Truth RPs)
    const results = useMemo(() => {
        return runSimulation(filteredDistributions, schedule, groundTruthRPs, matchLimit);
    }, [filteredDistributions, schedule, groundTruthRPs, matchLimit]);

    const resultsByTeam = useMemo(() => {
        const map = new Map<string, (typeof results)[number]>();
        results.forEach((row) => map.set(row.teamKey, row));
        return map;
    }, [results]);

    const topTeams = [...results].sort((a, b) => {
        const rA = historicalRankMap[a.teamKey] || 999;
        const rB = historicalRankMap[b.teamKey] || 999;
        return rA - rB;
    }).slice(0, 15).map((r) => {
        const teamNum = parseInt(r.teamKey.replace('frc', ''), 10);
        const sbData = statboticsByTeamNum.get(teamNum);
        const teamReports = (reportsByTeam.get(r.teamKey) ?? []).filter(rep => rep.matchNum <= matchLimit);
        const ourEPA = calculateTeamEPA(teamReports).toFixed(1);

        const simResult = resultsByTeam.get(r.teamKey);
        const top8Count = simResult
            ? Object.entries(simResult.rankDistribution)
                .filter(([rank]) => parseInt(rank, 10) <= 8)
                .reduce((acc, [, cnt]) => acc + cnt, 0)
            : 0;
        const top8Prob = (top8Count / 10000 * 100).toFixed(0);
        const simExpectedRank = simResult ? Math.round(simResult.expectedRank) : 999;

        return {
            teamKey: r.teamKey,
            team: r.teamKey.replace('frc', ''),
            name: teamNameMap[r.teamKey] || 'UNIT',
            expected: simExpectedRank,
            actual: historicalRankMap[r.teamKey] || '?',
            prob: `${top8Prob}%`,
            rp: r.avgRP.toFixed(1),
            ourEPA,
            sbEPA: sbData?.epa?.breakdown?.total_points?.toFixed(1) || 'N/A'
        };
    });

    // 4. Generate Match Predictions for upcoming matches
    const matchPredictions = useMemo(() => {
        return predictUpcomingMatches(schedule, filteredDistributions, matchLimit);
    }, [schedule, filteredDistributions, matchLimit]);

    const matchPredictionMap = useMemo(() => {
        const map: Record<string, (typeof matchPredictions)[number]> = {};
        matchPredictions.forEach((prediction) => {
            map[prediction.matchKey] = prediction;
        });
        return map;
    }, [matchPredictions]);

    // 5. Build a quick lookup for played match results (score + winner)
    const playedResultsMap = useMemo(() => {
        const map: Record<string, { redScore: number; blueScore: number; winner: 'red' | 'blue' | 'tie' }> = {};
        tbaMatchesRaw.forEach((m) => {
            const key = m.key ?? m.matchKey;
            if (!key || !m.alliances) return;
            const redScore: number = m.alliances.red?.score ?? -1;
            const blueScore: number = m.alliances.blue?.score ?? -1;
            if (redScore < 0 || blueScore < 0) return;
            map[key] = {
                redScore,
                blueScore,
                winner: redScore > blueScore ? 'red' : blueScore > redScore ? 'blue' : 'tie',
            };
        });
        return map;
    }, [tbaMatchesRaw]);

    const epaCards = useMemo(() => {
        return Array.from(reportsByTeam.entries())
            .map(([teamKey, teamReports]) => {
                const teamNum = parseInt(teamKey.replace('frc', ''), 10);
                const ourEPAValue = calculateTeamEPA(teamReports);
                const ourEPA = ourEPAValue.toFixed(1);

                const sbData = statboticsByTeamNum.get(teamNum);
                const sbPoints = sbData?.epa?.breakdown?.total_points;
                const sbEPA = sbPoints != null ? sbPoints.toFixed(1) : 'N/A';

                const diffValue = sbPoints != null ? ourEPAValue - sbPoints : 0;
                const diff = diffValue.toFixed(1);
                const diffColor = diffValue > 0 ? '#22c55e' : diffValue < 0 ? '#ef4444' : '#888';

                return {
                    teamKey,
                    teamNum,
                    name: teamNameMap[teamKey] || 'TEAM',
                    ourEPA,
                    ourEPAValue,
                    sbEPA,
                    diff,
                    diffColor,
                };
            })
            .sort((a, b) => b.ourEPAValue - a.ourEPAValue);
    }, [reportsByTeam, statboticsByTeamNum, teamNameMap]);

    return (
        <main style={{ minHeight: '100vh', background: 'var(--background)', color: 'var(--foreground)', padding: 'clamp(5.5rem, 8vw, 2.5rem) clamp(1rem, 4vw, 1.25rem) 2rem', overflow: 'hidden' }}>
            <div className="mx-auto responsive-padding" style={{ maxWidth: '1200px', display: 'grid', gap: '2rem', width: '100%' }}>

                <header className="flex flex-col md:flex-row justify-between items-start md:items-end reveal mobile-stack" style={{ gap: '1.5rem' }}>
                    <div style={{ display: 'grid', gap: '0.6rem' }}>
                        <div className="flex items-center" style={{ gap: '0.75rem' }}>
                            <div style={{ width: '8px', height: '8px', borderRadius: '50%', background: 'var(--primary-teal)', boxShadow: '0 0 12px var(--primary-teal)' }}></div>
                            <p style={{ fontSize: '11px', fontWeight: 950, letterSpacing: '0.2em', textTransform: 'uppercase', color: 'var(--primary-teal)' }}>⚙ {eventKey.split('2026')[1]?.toUpperCase() || eventKey.toUpperCase()} DASHBOARD</p>
                        </div>
                        <h1 style={{ fontSize: 'clamp(2.8rem, 10vw, 5.5rem)', fontWeight: 950, letterSpacing: '-0.03em', lineHeight: 1, background: 'linear-gradient(135deg, var(--primary-teal) 0%, var(--primary-brown) 100%)', backgroundClip: 'text', WebkitBackgroundClip: 'text', color: 'transparent' }}>
                            {eventKey.toUpperCase()}
                        </h1>
                        <p style={{ color: 'var(--muted)', fontSize: '1rem', fontWeight: 500 }}>Match simulation and point-in-time ranking view</p>
                    </div>

                    <div className="w-full md:w-auto event-header-actions" style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap', justifyContent: 'center' }}>
                        <Link href={`/event/${eventKey}/teams`} style={{ textDecoration: 'none', flex: '1 1 auto', minWidth: '90px', maxWidth: '150px' }}>
                            <div className="glass" style={{ padding: '0.65rem 0.85rem', borderRadius: '999px', border: '1px solid rgba(255,255,255,0.16)', background: 'rgba(255, 255, 255, 0.03)', textAlign: 'center', whiteSpace: 'nowrap' }}>
                                <p style={{ fontSize: '9px', fontWeight: 650, color: 'var(--foreground)', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                    Teams
                                </p>
                            </div>
                        </Link>
                        <Link href={`/scouters/${eventKey}`} style={{ textDecoration: 'none', flex: '1 1 auto', minWidth: '100px', maxWidth: '150px' }}>
                            <div className="glass" style={{ padding: '0.65rem 0.85rem', borderRadius: '999px', border: '1px solid rgba(124,109,216,0.35)', background: 'rgba(124,109,216,0.08)', textAlign: 'center', whiteSpace: 'nowrap' }}>
                                <p style={{ fontSize: '9px', fontWeight: 650, color: 'var(--primary)', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                    Scouter Intel
                                </p>
                            </div>
                        </Link>
                        <Link href={`/event/${eventKey}/draft`} style={{ textDecoration: 'none', flex: '1 1 auto', minWidth: '95px', maxWidth: '150px' }}>
                            <div className="glass" style={{ padding: '0.65rem 0.85rem', borderRadius: '999px', border: '1px solid rgba(79,174,192,0.35)', background: 'rgba(79,174,192,0.08)', textAlign: 'center', whiteSpace: 'nowrap' }}>
                                <p style={{ fontSize: '9px', fontWeight: 650, color: 'var(--secondary)', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                    Draft Advisor
                                </p>
                            </div>
                        </Link>
                        <Link href={`/event/${eventKey}/alliance-sim`} style={{ textDecoration: 'none', flex: '1 1 auto', minWidth: '105px', maxWidth: '150px' }}>
                            <div className="glass" style={{ padding: '0.65rem 0.85rem', borderRadius: '999px', border: '1px solid rgba(99,143,209,0.35)', background: 'rgba(99,143,209,0.08)', textAlign: 'center', whiteSpace: 'nowrap' }}>
                                <p style={{ fontSize: '9px', fontWeight: 650, color: '#76a8df', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                    Alliance Sim
                                </p>
                            </div>
                        </Link>
                        <Link href={`/event/${eventKey}/compare`} style={{ textDecoration: 'none', flex: 1 }}>
                            <div className="glass" style={{ padding: '0.75rem 1rem', borderRadius: '999px', border: '1px solid rgba(213,182,90,0.35)', background: 'rgba(213,182,90,0.08)', textAlign: 'center' }}>
                                <p style={{ fontSize: '10px', fontWeight: 650, color: '#d5b65a' }}>
                                    Compare
                                </p>
                            </div>
                        </Link>
                        <Link href="/quick-scout" style={{ textDecoration: 'none', flex: 1 }}>
                            <div className="glass" style={{ padding: '0.75rem 1rem', borderRadius: '999px', border: '1px solid rgba(205,93,116,0.35)', background: 'rgba(205,93,116,0.08)', textAlign: 'center' }}>
                                <p style={{ fontSize: '10px', fontWeight: 650, color: 'var(--accent)' }}>
                                    Quick Scout
                                </p>
                            </div>
                        </Link>
                        <Link href={`/event/${eventKey}/anomalies`} style={{ textDecoration: 'none', flex: 1 }}>
                            <div className="glass" style={{ padding: '0.75rem 1rem', borderRadius: '999px', border: '1px solid rgba(172,36,36,0.35)', background: 'rgba(172,36,36,0.08)', textAlign: 'center' }}>
                                <p style={{ fontSize: '10px', fontWeight: 650, color: 'var(--secondary-red)' }}>
                                    Anomalies
                                </p>
                            </div>
                        </Link>
                    </div>
                </header>


                {/* Simulation Control (Slider) */}
                <section className="reveal delay-2">
                    <div className="glass" style={{ padding: '1.4rem', borderRadius: '24px' }}>
                        <div className="flex justify-between items-center mobile-stack" style={{ marginBottom: '1rem' }}>
                            <h3 style={{ fontSize: '10px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: '0.1em' }}>Point-in-Time Analysis</h3>
                            <span style={{ fontSize: 'clamp(1.1rem, 4vw, 1.4rem)', fontWeight: 760, color: 'var(--primary)' }}>Up to Match {matchLimit}</span>
                        </div>
                        <input
                            type="range" min="0" max={maxMatch} value={matchLimit}
                            onChange={(e) => setMatchLimit(parseInt(e.target.value))}
                            style={{ width: '100%', height: '8px', borderRadius: '10px', background: 'rgba(255,255,255,0.05)', accentColor: 'var(--primary)', cursor: 'pointer' }}
                        />
                        <div className="flex justify-between" style={{ marginTop: '0.5rem' }}>
                            <span style={{ fontSize: '9px', fontWeight: 650, color: 'var(--muted)' }}>Pre-event</span>
                            <span style={{ fontSize: '9px', fontWeight: 650, color: 'var(--muted)' }}>Current</span>
                        </div>
                    </div>
                </section>

                {/* Main Body Grid */}
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '1rem' }}>

                    {/* Left: Leaderboard */}
                    <div style={{ gridColumn: 'span min(3, 4)', display: 'grid', gap: '2rem' }} className="reveal delay-3">
                        <div className="flex justify-between items-center" style={{ paddingBottom: '0.8rem', borderBottom: '1px solid rgba(255,255,255,0.08)' }}>
                            <div className="flex items-center gap-4">
                                <h2 style={{ fontSize: '11px', fontWeight: 700, letterSpacing: '0.08em', textTransform: 'uppercase', color: 'var(--muted)' }}>TBA Rankings (Match {matchLimit})</h2>
                                <button
                                    onClick={() => {
                                        const exportData: ExportableTeam[] = topTeams.map((t, index) => ({
                                            rank: index + 1,
                                            teamNumber: t.team,
                                            teamName: t.name,
                                            ourEPA: parseFloat(t.ourEPA),
                                            sbEPA: t.sbEPA === 'N/A' ? null : parseFloat(t.sbEPA),
                                            failureRate: 0, // Placeholder
                                            consistencyScore: 50, // Placeholder
                                            notes: ""
                                        }));
                                        exportToCSV(exportData, `${eventKey}_rankings`);
                                    }}
                                    className="glass-button"
                                    style={{
                                        padding: '0.4rem 0.8rem',
                                        fontSize: '9px',
                                        fontWeight: 950,
                                        color: 'var(--primary)',
                                        borderRadius: '10px',
                                        border: '1px solid rgba(124,109,216,0.5)',
                                        background: 'rgba(124,109,216,0.08)',
                                        cursor: 'pointer',
                                        textTransform: 'uppercase'
                                    }}
                                >
                                    Export CSV
                                </button>
                            </div>
                            <span style={{ fontSize: '9px', fontWeight: 650, color: 'var(--muted)' }}>Samples: {filteredDistributions.reduce((acc, d) => acc + d.pastSyntheticMatches.length, 0)}</span>
                        </div>

                        <div style={{ display: 'grid', gap: '0.85rem' }}>
                            {topTeams.map((p) => (
                                <Link key={p.teamKey} href={`/event/${eventKey}/team/${p.teamKey}`} style={{ textDecoration: 'none', color: 'inherit' }}>
                                    <div className="glass flex items-center leaderboard-card" style={{ padding: '1.2rem', gap: '1.25rem', borderRadius: '22px', border: '1px solid rgba(255,255,255,0.08)' }}>
                                        <div className="flex items-center gap-8 rank-pill">
                                            <div style={{ textAlign: 'center' }}>
                                                <p style={{ fontSize: '10px', fontWeight: 700, color: 'var(--primary)', textTransform: 'uppercase', letterSpacing: '0.06em' }}>TBA</p>
                                                <span style={{ fontSize: '2.2rem', fontWeight: 760, color: 'var(--foreground)' }}>#{p.actual}</span>
                                            </div>
                                            <div className="rank-divider" style={{ width: '1px', height: '2.3rem', background: 'rgba(255,255,255,0.12)' }}></div>
                                            <div style={{ textAlign: 'center' }}>
                                                <p style={{ fontSize: '10px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: '0.06em' }}>SIM</p>
                                                <span style={{ fontSize: '1.8rem', fontWeight: 760, color: p.actual === p.expected ? 'var(--secondary)' : 'var(--muted)' }}>#{p.expected}</span>
                                            </div>
                                        </div>

                                        <div style={{ flex: 1 }}>
                                            <p style={{ fontSize: '11px', fontWeight: 700, color: 'var(--primary)', letterSpacing: '0.06em' }}>Team {p.team}</p>
                                            <h3 style={{ fontSize: 'clamp(1.1rem, 3vw, 1.5rem)', fontWeight: 720, color: 'var(--foreground)', lineHeight: 1.1 }}>{p.name}</h3>
                                        </div>

                                        <div className="flex items-center gap-8 mobile-stack">
                                            <div>
                                                <p style={{ fontSize: '10px', fontWeight: 700, color: 'var(--primary)', textTransform: 'uppercase' }}>Our EPA</p>
                                                <p style={{ fontSize: 'clamp(1.05rem, 3vw, 1.35rem)', fontWeight: 760, color: 'var(--foreground)', fontFamily: 'monospace' }}>{p.ourEPA}</p>
                                            </div>
                                            <div className="rank-divider" style={{ width: '1px', height: '2.2rem', background: 'rgba(255,255,255,0.12)' }}></div>
                                            <div>
                                                <p style={{ fontSize: '10px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase' }}>SB EPA</p>
                                                <p style={{ fontSize: 'clamp(1.05rem, 3vw, 1.35rem)', fontWeight: 700, color: '#d0d5de', fontFamily: 'monospace' }}>{p.sbEPA}</p>
                                            </div>
                                            <div className="rank-divider" style={{ width: '1px', height: '2.2rem', background: 'rgba(255,255,255,0.12)' }}></div>
                                            <div style={{ textAlign: 'right' }}>
                                                <p style={{ fontSize: '10px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase' }}>Top 8</p>
                                                <div style={{ fontSize: 'clamp(1.1rem, 3vw, 1.5rem)', fontWeight: 760, color: 'var(--secondary)' }}>
                                                    {p.prob}
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>

                    {/* Right: Insights */}
                    <div style={{ display: 'grid', gap: '2rem' }} className="reveal delay-4">
                        <section className="glass" style={{ padding: '1.4rem', borderRadius: '22px' }}>
                            <h3 style={{ fontSize: '10px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '1rem' }}>Simulation Health</h3>
                            <p style={{ fontSize: '0.86rem', color: '#c7ced7', lineHeight: 1.5, marginBottom: '1rem' }}>
                                {matchLimit === 0
                                    ? "Pre-event baseline. Based on generic synthetic samples."
                                    : `Point-in-time snapshot using real data up to Match ${matchLimit}.`}
                            </p>
                            <div style={{ height: '4px', background: 'rgba(255,255,255,0.06)', borderRadius: '10px' }}>
                                <div style={{ height: '100%', borderRadius: '10px', background: '#84caa7', width: `${Math.min(100, (matchLimit / maxMatch) * 100)}%` }}></div>
                            </div>
                        </section>
                    </div>
                </div>

                {/* Tactical Schedule */}
                <div className="reveal delay-5" style={{ marginTop: '1rem' }}>
                    <div className="flex justify-between items-end" style={{ marginBottom: '1.5rem' }}>
                        <div>
                            <h2 style={{ fontSize: '1.25rem', fontWeight: 760, marginBottom: '0.5rem' }}>Match Schedule</h2>
                            <p style={{ fontSize: '11px', color: 'var(--muted)', fontWeight: 600 }}>Per-match score and win probability view</p>
                        </div>
                    </div>

                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '1rem' }}>
                        {schedule.map((m: SimulatedMatch) => {
                            const mNum = parseInt(m.matchKey.split('_qm').pop() || '0');
                            const isPlayed = mNum <= matchLimit;
                            const result = playedResultsMap[m.matchKey];
                            return (
                                <Link key={m.matchKey} href={`/match/${m.matchKey}`} style={{ textDecoration: 'none', opacity: isPlayed ? 0.75 : 1 }}>
                                    <div className="glass" style={{ padding: '1rem', borderRadius: '18px', border: isPlayed ? '1px solid rgba(255,255,255,0.06)' : '1px solid rgba(255,255,255,0.1)' }}>
                                        <div className="flex justify-between items-center" style={{ marginBottom: '0.8rem' }}>
                                            <span style={{ fontSize: '11px', fontWeight: 700, color: isPlayed ? 'var(--muted)' : 'var(--primary)' }}>{m.matchKey.split('_').pop()?.toUpperCase() || 'QM?'}</span>
                                            {isPlayed && result ? (
                                                <span style={{
                                                    fontSize: '9px', fontWeight: 700, textTransform: 'uppercase',
                                                    color: result.winner === 'tie' ? '#d5b65a' : result.winner === 'red' ? '#cd5d74' : '#76a8df'
                                                }}>
                                                    {result.winner === 'tie' ? '⚖ TIE' : result.winner === 'red' ? ' RED WIN' : ' BLUE WIN'}
                                                </span>
                                            ) : isPlayed ? (
                                                <span style={{ fontSize: '9px', fontWeight: 700, color: '#84caa7' }}>Complete</span>
                                            ) : (
                                                <span style={{ fontSize: '9px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase' }}>Preview</span>
                                            )}
                                        </div>
                                        <div style={{ display: 'grid', gap: '0.75rem' }}>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '0.5rem', background: isPlayed && result?.winner === 'red' ? 'rgba(205,93,116,0.14)' : 'rgba(205,93,116,0.08)', padding: '0.5rem', borderRadius: '10px' }}>
                                                <div style={{ display: 'flex', gap: '0.5rem' }}>
                                                    {m.red.map((t: string) => <span key={t} style={{ color: '#cd5d74', fontSize: '12px', fontWeight: 700 }}>{t.replace('frc', '')}</span>)}
                                                </div>
                                                {result && <span style={{ fontSize: '1rem', fontWeight: 760, color: result.winner === 'red' ? '#cd5d74' : 'var(--muted)', fontFamily: 'monospace' }}>{result.redScore}</span>}
                                            </div>
                                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '0.5rem', background: isPlayed && result?.winner === 'blue' ? 'rgba(118,168,223,0.14)' : 'rgba(118,168,223,0.08)', padding: '0.5rem', borderRadius: '10px' }}>
                                                <div style={{ display: 'flex', gap: '0.5rem' }}>
                                                    {m.blue.map((t: string) => <span key={t} style={{ color: '#76a8df', fontSize: '12px', fontWeight: 700 }}>{t.replace('frc', '')}</span>)}
                                                </div>
                                                {result && <span style={{ fontSize: '1rem', fontWeight: 760, color: result.winner === 'blue' ? '#76a8df' : 'var(--muted)', fontFamily: 'monospace' }}>{result.blueScore}</span>}
                                            </div>
                                            {!isPlayed && (() => {
                                                const prediction = matchPredictionMap[m.matchKey];
                                                if (!prediction) return null;
                                                const confColor = prediction.confidence === 'high' ? '#22c55e' : prediction.confidence === 'medium' ? '#eab308' : '#ef4444';
                                                return (
                                                    <div style={{ marginTop: '0.45rem', padding: '0.65rem', background: 'rgba(255,255,255,0.02)', borderRadius: '10px', borderLeft: `2px solid ${confColor}` }}>
                                                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.5rem' }}>
                                                            <span style={{ fontSize: '9px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase' }}>Win Probability</span>
                                                            <span style={{ fontSize: '9px', fontWeight: 700, color: confColor, textTransform: 'uppercase' }}>{prediction.confidence}</span>
                                                        </div>
                                                        <div style={{ display: 'grid', gridTemplateColumns: '1fr auto 1fr', gap: '0.5rem', alignItems: 'center' }}>
                                                            <div style={{ textAlign: 'center' }}>
                                                                <div style={{ fontSize: '1.1rem', fontWeight: 760, color: '#cd5d74' }}>{(prediction.redWinProbability * 100).toFixed(0)}%</div>
                                                                <div style={{ fontSize: '9px', color: 'var(--muted)' }}>{prediction.redScoreRange.mean.toFixed(0)} pts</div>
                                                            </div>
                                                            <div style={{ fontSize: '10px', color: 'var(--muted)' }}>vs</div>
                                                            <div style={{ textAlign: 'center' }}>
                                                                <div style={{ fontSize: '1.1rem', fontWeight: 760, color: '#76a8df' }}>{(prediction.blueWinProbability * 100).toFixed(0)}%</div>
                                                                <div style={{ fontSize: '9px', color: 'var(--muted)' }}>{prediction.blueScoreRange.mean.toFixed(0)} pts</div>
                                                            </div>
                                                        </div>
                                                    </div>
                                                );
                                            })()}
                                            {isPlayed && result && (() => {
                                                const prediction = matchPredictionMap[m.matchKey];
                                                if (!prediction) return null;
                                                const predictedWinner = prediction.redWinProbability >= prediction.blueWinProbability ? 'red' : 'blue';
                                                const correct = predictedWinner === result.winner || result.winner === 'tie';
                                                return (
                                                    <div style={{ padding: '0.5rem 0.75rem', background: 'rgba(255,255,255,0.02)', borderRadius: '8px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                                        <span style={{ fontSize: '9px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase' }}>Predicted</span>
                                                        <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'center' }}>
                                                            <span style={{ fontSize: '9px', fontWeight: 700, color: '#cd5d74' }}>{(prediction.redWinProbability * 100).toFixed(0)}%R</span>
                                                            <span style={{ fontSize: '9px', color: 'var(--muted)' }}>·</span>
                                                            <span style={{ fontSize: '9px', fontWeight: 700, color: '#76a8df' }}>{(prediction.blueWinProbability * 100).toFixed(0)}%B</span>
                                                            <span style={{ fontSize: '9px', fontWeight: 700, color: correct ? '#84caa7' : '#cd5d74' }}>{correct ? '✓' : '✗'}</span>
                                                        </div>
                                                    </div>
                                                );
                                            })()}
                                        </div>
                                    </div>
                                </Link>
                            );
                        })}
                    </div>
                </div>

                {/* EPA Analysis Section */}
                <div className="reveal delay-6" style={{ marginTop: '1rem' }}>
                    <h2 style={{ fontSize: '1.2rem', fontWeight: 760, marginBottom: '1rem' }}>EPA Analysis (Our Data vs Statbotics)</h2>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '0.85rem' }}>
                        {epaCards.map((card) => (
                            <div key={card.teamKey} className="glass" style={{ padding: '1.15rem', borderRadius: '16px', border: '1px solid rgba(255,255,255,0.08)' }}>
                                <div className="flex justify-between items-center" style={{ marginBottom: '0.8rem' }}>
                                    <span style={{ fontSize: '1.1rem', fontWeight: 760, color: 'var(--primary)' }}>{card.teamNum}</span>
                                    <span style={{ fontSize: '0.72rem', fontWeight: 600, color: 'var(--muted)' }}>{card.name}</span>
                                </div>

                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <p style={{ fontSize: '9px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase' }}>Our EPA</p>
                                        <p style={{ fontSize: '1.3rem', fontWeight: 760, color: 'var(--foreground)' }}>{card.ourEPA}</p>
                                    </div>
                                    <div>
                                        <p style={{ fontSize: '9px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase' }}>Statbotics</p>
                                        <p style={{ fontSize: '1.3rem', fontWeight: 700, color: '#d0d5de' }}>{card.sbEPA}</p>
                                    </div>
                                </div>

                                <div style={{ marginTop: '0.8rem', paddingTop: '0.8rem', borderTop: '1px solid rgba(255,255,255,0.08)' }}>
                                    <p style={{ fontSize: '9px', fontWeight: 700, color: 'var(--muted)', textTransform: 'uppercase' }}>Difference</p>
                                    <p style={{ fontSize: '1rem', fontWeight: 760, color: card.diffColor }}>{parseFloat(card.diff) > 0 ? '+' : ''}{card.diff}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

            </div >
        </main >
    );
}

'use client';

import { useState } from 'react';
import { getTacticalStrategy } from '@/lib/actions';
import ReactMarkdown from 'react-markdown';

interface PredictedMatchData {
    predictedPts: number;
    predictedAuto: number;
    predictedTele: number;
    predictedTower: number;
    sampleSize: number;
}

interface ActualMatchData {
    autoFuel: number;
    teleFuel: number;
    autoClimb: string;
    teleClimb: string;
    towerPts: number;
    autoMoved: boolean;
    mechFailure: boolean;
    defenderRating: number;
    notes: string;
    scoutedBy: string;
}

interface TeamProfile {
    teamKey: string;
    teamNum: string;
    avgAutoFuel: string;
    avgTeleopFuel: string;
    avgFuel: string;
    avgTowerPts: string;
    bestTowerLevel: string;
    autoMobility: string;
    autoFuel: string;
    towerRate: string;
    avgDefense: string;
    hubControl: string;
    trenchCapable: string;
    failures: number;
    notes: string;
    predicted: PredictedMatchData;
    actual: ActualMatchData | null;
    pit?: {
        drivebase?: string;
        climb?: string;
        hopperCapacity?: number | null;
        trench?: string;
        bump?: string;
        canLob?: string;
        turret?: string;
        shiftTracking?: string;
        pickupFloor?: string;
        pickupOutpost?: string;
        autoClimb?: string;
        robotQuality?: number;
        weightLbs?: number | null;
        heightIn?: number | null;
        otherNotes?: string;
    } | null;
}

interface TBAAllianceBreakdown {
    autoPoints: number | null;
    teleopPoints: number | null;
    endgamePoints: number | null;
    fuelPoints: number | null;
    autoFuelPoints: number | null;
    teleopFuelPoints: number | null;
    towerEndgamePoints: number | null;
    rp: number | null;
}

interface TBAResult {
    redScore: number;
    blueScore: number;
    winner: 'red' | 'blue' | 'tie';
    red: TBAAllianceBreakdown;
    blue: TBAAllianceBreakdown;
}

interface Props {
    matchKey: string;
    eventKey: string;
    redProfiles: TeamProfile[];
    blueProfiles: TeamProfile[];
    isPlayed: boolean;
    tbaResult: TBAResult | null;
    redPredicted: number;
    bluePredicted: number;
}

const CLIMB_LABEL: Record<string, string> = { Level3: 'L3 ', Level2: 'L2', Level1: 'L1', 'No Attempt': '—', None: '—' };

function AllianceBreakdown({
    profiles,
    alliance,
    tba,
    totalScore,
    eventKey,
}: {
    profiles: TeamProfile[];
    alliance: 'red' | 'blue';
    tba: TBAAllianceBreakdown | null;
    totalScore: number;
    eventKey: string;
}) {
    const color = alliance === 'red' ? '#ef4444' : '#3b82f6';
    const bgWin = alliance === 'red' ? 'rgba(239,68,68,0.07)' : 'rgba(59,130,246,0.07)';

    // Sum up what scouts recorded for this alliance in this match
    const scoutedAutoFuel = profiles.reduce((s, p) => s + (p.actual?.autoFuel ?? 0), 0);
    const scoutedTeleFuel = profiles.reduce((s, p) => s + (p.actual?.teleFuel ?? 0), 0);
    const scoutedTowerPts = profiles.reduce((s, p) => s + (p.actual?.towerPts ?? 0), 0);

    // Official fuel pts from TBA (auto + tele fuel combined)
    const tbaTotalFuelPts = (tba?.fuelPoints ?? ((tba?.autoFuelPoints ?? 0) + (tba?.teleopFuelPoints ?? 0)));
    // Tower pts are fixed (10/20/30) — don't scale those
    const tbaNonTowerScore = totalScore - scoutedTowerPts;
    const scoutedNonTowerPts = scoutedAutoFuel + scoutedTeleFuel;

    // Scale factor: if scouts overcounted fuel, compress each robot's fuel proportionally
    // so that scaled fuel totals + tower pts = TBA total score
    const fuelScaleFactor = (scoutedNonTowerPts > 0 && tbaNonTowerScore > 0)
        ? Math.min(1, tbaNonTowerScore / scoutedNonTowerPts)
        : 1;
    const isScaled = Math.abs(fuelScaleFactor - 1) > 0.02; // only show scale indicator if >2% off

    // Human player contribution = TBA fuel pts − scaled robot fuel
    const scaledTotalFuel = scoutedNonTowerPts * fuelScaleFactor;
    const humanPlayerFuel = Math.max(0, tbaTotalFuelPts - scaledTotalFuel);

    const scoutCoverage = profiles.filter(p => p.actual !== null).length;

    return (
        <div style={{ background: bgWin, borderRadius: '30px', padding: '2rem', border: `1px solid ${color}22` }}>
            {/* Header */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
                <div>
                    <p style={{ fontSize: '9px', fontWeight: 950, color, textTransform: 'uppercase', letterSpacing: '0.2em' }}>{alliance} alliance</p>
                    <p style={{ fontSize: '3rem', fontWeight: 950, fontStyle: 'italic', color, lineHeight: 1 }}>{totalScore}</p>
                    {tba?.rp != null && <p style={{ fontSize: '9px', color: '#888', fontWeight: 700 }}>{tba.rp} RP</p>}
                </div>
                <div style={{ textAlign: 'right' }}>
                    {scoutCoverage < profiles.length && (
                        <p style={{ fontSize: '9px', color: '#eab308', fontWeight: 900 }}>⚠ {scoutCoverage}/{profiles.length} SCOUTED</p>
                    )}
                    {isScaled && (
                        <p style={{ fontSize: '9px', color: '#a855f7', fontWeight: 900 }}>⚖ SCALED ×{fuelScaleFactor.toFixed(2)}</p>
                    )}
                    {tba && (
                        <div style={{ fontSize: '9px', color: '#666', lineHeight: 1.6 }}>
                            {tba.autoPoints != null && <div>Auto: <span style={{ color: '#aaa' }}>{tba.autoPoints}pts</span></div>}
                            {tba.teleopPoints != null && <div>Teleop: <span style={{ color: '#aaa' }}>{tba.teleopPoints}pts</span></div>}
                            {tba.endgamePoints != null && <div>Endgame: <span style={{ color: '#aaa' }}>{tba.endgamePoints}pts</span></div>}
                        </div>
                    )}
                </div>
            </div>

            {/* Per-robot rows */}
            <div style={{ display: 'grid', gap: '0.75rem', marginBottom: '1.25rem' }}>
                {profiles.map(p => {
                    const a = p.actual;
                    const rawFuel = a ? a.autoFuel + a.teleFuel : 0;
                    const scaledFuel = Math.round(rawFuel * fuelScaleFactor);
                    const robotTotal = a ? scaledFuel + a.towerPts : null;
                    const rawTotal = a ? rawFuel + a.towerPts : null;
                    const pct = (robotTotal != null && totalScore > 0)
                        ? ((robotTotal / totalScore) * 100).toFixed(0)
                        : null;
                    return (
                        <a key={p.teamKey} href={`/event/${eventKey}/team/${p.teamKey}`}
                            style={{ textDecoration: 'none', color: 'inherit' }}>
                            <div style={{ background: 'rgba(0,0,0,0.3)', borderRadius: '18px', padding: '1rem 1.25rem', border: `1px solid ${a ? color + '33' : 'rgba(255,255,255,0.04)'}` }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: a ? '0.75rem' : 0 }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                                        <span style={{ fontSize: '1.25rem', fontWeight: 950, color }}>{p.teamNum}</span>
                                        {a?.mechFailure && <span style={{ fontSize: '8px', background: 'rgba(239,68,68,0.2)', color: '#ef4444', padding: '0.15rem 0.4rem', borderRadius: '5px', fontWeight: 900 }}>FAIL</span>}
                                        {a?.defenderRating && a.defenderRating > 0 && <span style={{ fontSize: '8px', background: 'rgba(234,179,8,0.15)', color: '#eab308', padding: '0.15rem 0.4rem', borderRadius: '5px', fontWeight: 900 }}>DEF {a.defenderRating}</span>}
                                        {!a && <span style={{ fontSize: '8px', color: '#444', fontWeight: 700 }}>not scouted this match</span>}
                                    </div>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                                        {robotTotal != null && (
                                            <span style={{ fontSize: '1.1rem', fontWeight: 950, color: '#fff', fontFamily: 'monospace' }}>
                                                {robotTotal}pts
                                            </span>
                                        )}
                                        {isScaled && rawTotal != null && rawTotal !== robotTotal && (
                                            <span style={{ fontSize: '8px', color: '#555', fontFamily: 'monospace' }}>({rawTotal} raw)</span>
                                        )}
                                        {/* Predicted score + diff */}
                                        <span style={{ fontSize: '8px', color: '#666', fontFamily: 'monospace' }}>
                                            pred <span style={{ color: '#a855f7' }}>{p.predicted.predictedPts}</span>
                                            {robotTotal != null && (
                                                <span style={{ color: Math.abs(robotTotal - p.predicted.predictedPts) < p.predicted.predictedPts * 0.2 ? '#22c55e' : '#eab308', marginLeft: '0.2rem' }}>
                                                    ({robotTotal >= p.predicted.predictedPts ? '+' : ''}{robotTotal - p.predicted.predictedPts})
                                                </span>
                                            )}
                                        </span>
                                        {pct != null && (
                                            <span style={{ fontSize: '9px', color: '#666', fontWeight: 700 }}>{pct}%</span>
                                        )}
                                    </div>
                                </div>

                                {a && (
                                    <>
                                        {/* Stat pills */}
                                        <div style={{ display: 'flex', gap: '0.4rem', flexWrap: 'wrap', marginBottom: '0.5rem' }}>
                                            <StatPill label="AUTO" value={`${Math.round(a.autoFuel * fuelScaleFactor)}⛽${isScaled ? ` (${a.autoFuel})` : ''}`} color={color} />
                                            <StatPill label="TELE" value={`${Math.round(a.teleFuel * fuelScaleFactor)}⛽${isScaled ? ` (${a.teleFuel})` : ''}`} color={color} />
                                            <StatPill label="TOWER" value={CLIMB_LABEL[a.teleClimb] ?? '—'} color={a.towerPts > 0 ? '#eab308' : '#444'} />
                                            {a.autoMoved && <StatPill label="" value="✓ AUTO MOV" color="#22c55e" />}
                                        </div>

                                        {/* Contribution bar — scaled pts vs TBA total */}
                                        {totalScore > 0 && robotTotal != null && (
                                            <div style={{ height: '4px', background: 'rgba(255,255,255,0.05)', borderRadius: '2px' }}>
                                                <div style={{ height: '100%', borderRadius: '2px', background: color, width: `${Math.min(100, (robotTotal / totalScore) * 100)}%`, transition: 'width 0.5s ease' }} />
                                            </div>
                                        )}

                                        {/* Notes */}
                                        {a.notes && (
                                            <p style={{ fontSize: '0.7rem', color: '#666', fontStyle: 'italic', marginTop: '0.4rem', lineHeight: 1.4 }}>
                                                &ldquo;{a.notes}&rdquo;
                                                <span style={{ color: '#444', marginLeft: '0.4rem' }}>— {a.scoutedBy}</span>
                                            </p>
                                        )}
                                    </>
                                )}

                                {/* Avg + predicted fallback for unscouted */}
                                {!a && (
                                    <div style={{ display: 'flex', gap: '0.4rem', flexWrap: 'wrap' }}>
                                        <StatPill label="PRED" value={`${p.predicted.predictedPts}pts`} color="#a855f7" />
                                        <StatPill label="AVG AUTO" value={p.avgAutoFuel} color="#555" />
                                        <StatPill label="AVG TELE" value={p.avgTeleopFuel} color="#555" />
                                        <StatPill label="AVG TWR" value={p.avgTowerPts} color="#555" />
                                        {p.predicted.sampleSize > 0 && <StatPill label="n=" value={String(p.predicted.sampleSize)} color="#333" />}
                                    </div>
                                )}
                            </div>
                        </a>
                    );
                })}
            </div>

            {/* Human Player contribution row */}
            {scoutCoverage > 0 && humanPlayerFuel > 0 && (
                <div style={{ background: 'rgba(6,182,212,0.07)', borderRadius: '14px', padding: '0.75rem 1.25rem', border: '1px solid rgba(6,182,212,0.15)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
                        <span style={{ fontSize: '0.9rem' }}></span>
                        <div>
                            <p style={{ fontSize: '9px', fontWeight: 950, color: '#06b6d4', textTransform: 'uppercase', letterSpacing: '0.1em' }}>Human Player</p>
                            <p style={{ fontSize: '8px', color: '#444' }}>TBA fuel − scouted robot fuel</p>
                        </div>
                    </div>
                    <div style={{ textAlign: 'right' }}>
                        <p style={{ fontSize: '1.1rem', fontWeight: 950, color: '#06b6d4', fontFamily: 'monospace' }}>~{humanPlayerFuel}pts</p>
                        <p style={{ fontSize: '8px', color: '#444' }}>{((humanPlayerFuel / totalScore) * 100).toFixed(0)}% of total</p>
                    </div>
                </div>
            )}

            {/* Scouted total vs TBA */}
            {scoutCoverage > 0 && tbaTotalFuelPts > 0 && (
                <div style={{ marginTop: '0.75rem', padding: '0.5rem 1rem', background: 'rgba(255,255,255,0.02)', borderRadius: '10px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <span style={{ fontSize: '8px', fontWeight: 900, color: '#444', textTransform: 'uppercase' }}>Fuel accuracy</span>
                    <span style={{ fontSize: '8px', fontWeight: 950, color: Math.abs((scoutedAutoFuel + scoutedTeleFuel) - tbaTotalFuelPts) < tbaTotalFuelPts * 0.15 ? '#22c55e' : '#eab308' }}>
                        {scoutedAutoFuel + scoutedTeleFuel} scouted · {tbaTotalFuelPts} TBA fuel
                        {' '}({(scoutedAutoFuel + scoutedTeleFuel) >= tbaTotalFuelPts ? '+' : ''}{(scoutedAutoFuel + scoutedTeleFuel) - tbaTotalFuelPts} diff)
                    </span>
                </div>
            )}
        </div>
    );
}

function StatPill({ label, value, color }: { label: string; value: string; color: string }) {
    return (
        <span style={{ fontSize: '8px', fontWeight: 900, background: `${color}18`, color, padding: '0.2rem 0.5rem', borderRadius: '6px', whiteSpace: 'nowrap' }}>
            {label && <span style={{ opacity: 0.7, marginRight: '0.25rem' }}>{label}</span>}
            {value}
        </span>
    );
}

export default function MatchTacticalInterface({ matchKey, eventKey, redProfiles, blueProfiles, isPlayed, tbaResult, redPredicted, bluePredicted }: Props) {
    const [selectedAlliance, setSelectedAlliance] = useState<'red' | 'blue'>('red');
    const [manualNotes, setManualNotes] = useState<Record<string, string>>({});
    const [briefing, setBriefing] = useState<string | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [view, setView] = useState<'breakdown' | 'strategy'>(isPlayed ? 'breakdown' : 'strategy');

    const activeProfiles = selectedAlliance === 'red' ? redProfiles : blueProfiles;
    const opponentProfiles = selectedAlliance === 'red' ? blueProfiles : redProfiles;

    const handleGenerate = async () => {
        setIsLoading(true);
        setBriefing(null);
        const updatedAllianceData = activeProfiles.map(p => ({
            ...p,
            notes: manualNotes[p.teamKey] ? `${p.notes} [OVERRIDE: ${manualNotes[p.teamKey]}]` : p.notes
        }));
        const result = await getTacticalStrategy(matchKey, selectedAlliance, updatedAllianceData, opponentProfiles);
        setBriefing(result);
        setIsLoading(false);
    };

    return (
        <div style={{ display: 'grid', gap: '3rem' }}>

            {/* View toggle for played matches */}
            {isPlayed && (
                <section className="reveal">
                    <div className="glass" style={{ padding: '1rem', borderRadius: '20px', display: 'flex', gap: '0.5rem', width: 'fit-content' }}>
                        {(['breakdown', 'strategy'] as const).map(v => (
                            <button key={v} onClick={() => setView(v)} style={{
                                padding: '0.6rem 1.5rem', borderRadius: '12px', border: 'none', fontWeight: 950, fontSize: '11px', cursor: 'pointer', letterSpacing: '0.05em', textTransform: 'uppercase',
                                background: view === v ? 'var(--primary)' : 'transparent',
                                color: view === v ? '#000' : '#555',
                            }}>
                                {v === 'breakdown' ? ' Match Breakdown' : ' Strategy View'}
                            </button>
                        ))}
                    </div>
                </section>
            )}

            {/* ── PLAYED MATCH BREAKDOWN ── */}
            {isPlayed && view === 'breakdown' && tbaResult && (
                <section className="reveal delay-1">
                    {/* Scoreboard */}
                    <div className="glass" style={{ padding: '1.5rem 2rem', borderRadius: '25px', marginBottom: '2rem', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '2rem' }}>
                        <div style={{ textAlign: 'center' }}>
                            <p style={{ fontSize: '9px', fontWeight: 950, color: '#ef4444', letterSpacing: '0.2em', textTransform: 'uppercase' }}>Red Alliance</p>
                            <p style={{ fontSize: '3.5rem', fontWeight: 950, fontStyle: 'italic', color: tbaResult.winner === 'red' ? '#ef4444' : '#888', lineHeight: 1 }}>{tbaResult.redScore}</p>
                            <p style={{ fontSize: '9px', color: '#555', fontWeight: 700 }}>
                                pred <span style={{ color: Math.abs(redPredicted - tbaResult.redScore) < tbaResult.redScore * 0.15 ? '#22c55e' : '#eab308' }}>{redPredicted}</span>
                                {' '}<span style={{ color: '#444' }}>({redPredicted >= tbaResult.redScore ? '+' : ''}{redPredicted - tbaResult.redScore})</span>
                            </p>
                        </div>
                        <div style={{ textAlign: 'center' }}>
                            <p style={{ fontSize: '1rem', fontWeight: 950, color: '#444' }}>VS</p>
                            <p style={{ fontSize: '9px', fontWeight: 950, color: tbaResult.winner === 'tie' ? '#eab308' : tbaResult.winner === 'red' ? '#ef4444' : '#3b82f6', marginTop: '0.25rem', textTransform: 'uppercase', letterSpacing: '0.1em' }}>
                                {tbaResult.winner === 'tie' ? '⚖ TIE' : `${tbaResult.winner.toUpperCase()} WINS`}
                            </p>
                            <p style={{ fontSize: '8px', color: '#333', marginTop: '0.5rem' }}>PRED {redPredicted} – {bluePredicted}</p>
                        </div>
                        <div style={{ textAlign: 'center' }}>
                            <p style={{ fontSize: '9px', fontWeight: 950, color: '#3b82f6', letterSpacing: '0.2em', textTransform: 'uppercase' }}>Blue Alliance</p>
                            <p style={{ fontSize: '3.5rem', fontWeight: 950, fontStyle: 'italic', color: tbaResult.winner === 'blue' ? '#3b82f6' : '#888', lineHeight: 1 }}>{tbaResult.blueScore}</p>
                            <p style={{ fontSize: '9px', color: '#555', fontWeight: 700 }}>
                                pred <span style={{ color: Math.abs(bluePredicted - tbaResult.blueScore) < tbaResult.blueScore * 0.15 ? '#22c55e' : '#eab308' }}>{bluePredicted}</span>
                                {' '}<span style={{ color: '#444' }}>({bluePredicted >= tbaResult.blueScore ? '+' : ''}{bluePredicted - tbaResult.blueScore})</span>
                            </p>
                        </div>
                    </div>

                    {/* Alliance breakdowns side by side */}
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(340px, 1fr))', gap: '1.5rem' }}>
                        <AllianceBreakdown profiles={redProfiles} alliance="red" tba={tbaResult.red} totalScore={tbaResult.redScore} eventKey={eventKey} />
                        <AllianceBreakdown profiles={blueProfiles} alliance="blue" tba={tbaResult.blue} totalScore={tbaResult.blueScore} eventKey={eventKey} />
                    </div>
                </section>
            )}

            {/* ── STRATEGY VIEW (upcoming OR toggle on played) ── */}
            {(!isPlayed || view === 'strategy') && (
                <>
                    {/* Alliance Control Center */}
                    <section className="reveal delay-1">
                        <div className="glass" style={{ padding: '2rem', borderRadius: '40px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <p style={{ fontSize: '10px', fontWeight: 950, color: '#888', textTransform: 'uppercase', letterSpacing: '0.2em', marginBottom: '0.5rem' }}>Tactical Focus</p>
                                <h2 style={{ fontSize: '1.5rem', fontWeight: 950, fontStyle: 'italic', textTransform: 'uppercase' }}>Alliance Selection</h2>
                            </div>
                            <div className="flex gap-4" style={{ background: 'rgba(255,255,255,0.03)', padding: '0.5rem', borderRadius: '100px', border: '1px solid rgba(255,255,255,0.05)' }}>
                                {(['red', 'blue'] as const).map(a => (
                                    <button key={a} onClick={() => setSelectedAlliance(a)} style={{
                                        padding: '0.75rem 2rem', borderRadius: '100px', border: 'none',
                                        background: selectedAlliance === a ? (a === 'red' ? '#ef4444' : '#3b82f6') : 'transparent',
                                        color: selectedAlliance === a ? '#fff' : '#444',
                                        fontWeight: 950, fontSize: '12px', cursor: 'pointer', transition: 'all 0.3s ease', textTransform: 'uppercase',
                                    }}>{a} Alliance</button>
                                ))}
                            </div>
                        </div>
                    </section>

                    {/* Team Scoring Dashboard */}
                    <section className="reveal delay-2">
                        <div className="flex items-center gap-4" style={{ marginBottom: '2rem' }}>
                            <div style={{ width: '8px', height: '8px', borderRadius: '50%', background: selectedAlliance === 'red' ? '#ef4444' : '#3b82f6', boxShadow: `0 0 10px ${selectedAlliance === 'red' ? '#ef4444' : '#3b82f6'}` }}></div>
                            <h3 style={{ fontSize: '11px', fontWeight: 950, letterSpacing: '0.3em', textTransform: 'uppercase', color: '#444' }}>Allied Unit Readiness</h3>
                            <div style={{ marginLeft: 'auto', display: 'flex', gap: '1.5rem' }}>
                                <div style={{ textAlign: 'center' }}>
                                    <p style={{ fontSize: '8px', fontWeight: 900, color: '#ef4444', textTransform: 'uppercase' }}>Red Pred</p>
                                    <p style={{ fontSize: '1rem', fontWeight: 950, color: '#ef4444', fontFamily: 'monospace' }}>{redPredicted}</p>
                                </div>
                                <div style={{ fontSize: '10px', color: '#333', alignSelf: 'center' }}>vs</div>
                                <div style={{ textAlign: 'center' }}>
                                    <p style={{ fontSize: '8px', fontWeight: 900, color: '#3b82f6', textTransform: 'uppercase' }}>Blue Pred</p>
                                    <p style={{ fontSize: '1rem', fontWeight: 950, color: '#3b82f6', fontFamily: 'monospace' }}>{bluePredicted}</p>
                                </div>
                            </div>
                        </div>

                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: '1.5rem' }}>
                            {activeProfiles.map((p) => (
                                <div key={p.teamKey} className="glass" style={{ padding: '2rem', borderRadius: '35px', borderLeft: `4px solid ${selectedAlliance === 'red' ? '#ef4444' : '#3b82f6'}33` }}>
                                    <div className="flex justify-between items-start" style={{ marginBottom: '1.5rem' }}>
                                        <div>
                                            <h4 style={{ fontSize: '2.5rem', fontWeight: 950, fontStyle: 'italic', color: '#fff', lineHeight: 1 }}>{p.teamNum}</h4>
                                            <p style={{ fontSize: '9px', fontWeight: 950, color: '#888', textTransform: 'uppercase', letterSpacing: '0.1em' }}>Tactical Unit</p>
                                        </div>
                                        <div style={{ textAlign: 'right' }}>
                                            <div style={{ fontSize: '1.25rem', fontWeight: 950, color: '#a855f7', fontFamily: 'monospace', lineHeight: 1 }}>
                                                {p.predicted.predictedPts}pts
                                            </div>
                                            <p style={{ fontSize: '8px', color: '#555', fontWeight: 700 }}>
                                                {p.predicted.predictedAuto}a + {p.predicted.predictedTele}t + {p.predicted.predictedTower}e
                                                {p.predicted.sampleSize > 0 && <span style={{ color: '#333', marginLeft: '0.25rem' }}>n={p.predicted.sampleSize}</span>}
                                            </p>
                                            <p style={{ fontSize: '9px', fontWeight: 950, color: '#aaa', marginTop: '0.25rem' }}>HUB: {p.hubControl?.toUpperCase()}</p>
                                            {p.pit && <span style={{ fontSize: '8px', fontWeight: 950, background: 'rgba(168,85,247,0.2)', color: '#a855f7', padding: '0.15rem 0.4rem', borderRadius: '6px', marginTop: '0.3rem', display: 'inline-block' }}>PIT ✓</span>}
                                        </div>
                                    </div>

                                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '0.75rem', marginBottom: '1rem' }}>
                                        {[
                                            { label: 'AUTO FUEL', val: p.avgAutoFuel },
                                            { label: 'TELE FUEL', val: p.avgTeleopFuel },
                                            { label: 'TOWER PTS', val: p.avgTowerPts },
                                            { label: 'TOWER %', val: `${p.towerRate}%` },
                                            { label: 'TRENCH', val: p.trenchCapable, color: p.trenchCapable === 'Yes' ? '#22c55e' : '#666' },
                                            { label: 'DEFENSE', val: p.avgDefense },
                                        ].map(({ label, val, color }) => (
                                            <div key={label} style={{ background: 'rgba(255,255,255,0.02)', padding: '0.75rem', borderRadius: '15px', textAlign: 'center' }}>
                                                <p style={{ fontSize: '7px', fontWeight: 950, color: '#888' }}>{label}</p>
                                                <p style={{ fontSize: '1.25rem', fontWeight: 950, color: color ?? '#fff' }}>{val}</p>
                                            </div>
                                        ))}
                                    </div>

                                    {p.pit && (
                                        <div style={{ marginBottom: '1rem', padding: '0.75rem', background: 'rgba(168,85,247,0.06)', borderRadius: '12px', border: '1px solid rgba(168,85,247,0.15)' }}>
                                            <p style={{ fontSize: '8px', fontWeight: 950, color: '#a855f7', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '0.5rem' }}>Pit Intel</p>
                                            <div style={{ display: 'flex', gap: '0.4rem', flexWrap: 'wrap' }}>
                                                {p.pit.drivebase && <StatPill label="" value={p.pit.drivebase} color="#888" />}
                                                {p.pit.climb && p.pit.climb !== 'No Attempt' && <StatPill label="Max" value={p.pit.climb} color="#eab308" />}
                                                {p.pit.hopperCapacity != null && <StatPill label="Hopper" value={String(p.pit.hopperCapacity)} color="#c084fc" />}
                                                {p.pit.turret === 'Yes' && <StatPill label="" value="Turret" color="#22c55e" />}
                                                {p.pit.canLob === 'Yes' && <StatPill label="" value="Lob" color="#06b6d4" />}
                                                {p.pit.robotQuality != null && <StatPill label="Quality" value={`${p.pit.robotQuality}/5`} color="#aaa" />}
                                            </div>
                                        </div>
                                    )}

                                    <div>
                                        <p style={{ fontSize: '8px', fontWeight: 950, color: selectedAlliance === 'red' ? '#ef4444' : '#3b82f6', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '0.5rem' }}>Intelligence Overrides</p>
                                        <textarea
                                            placeholder="Enter field observations..."
                                            value={manualNotes[p.teamKey] || ''}
                                            onChange={(e) => setManualNotes({ ...manualNotes, [p.teamKey]: e.target.value })}
                                            style={{ width: '100%', height: '80px', background: 'rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.05)', borderRadius: '15px', padding: '1rem', color: '#ccc', fontSize: '11px', resize: 'none', fontFamily: 'inherit' }}
                                        />
                                    </div>
                                </div>
                            ))}
                        </div>
                    </section>

                    {/* AI Generation */}
                    <section className="reveal delay-3 flex flex-col items-center" style={{ marginTop: '2rem' }}>
                        <button onClick={handleGenerate} disabled={isLoading} className="generate-btn" style={{
                            padding: '1.5rem 4rem', borderRadius: '100px', border: 'none',
                            background: isLoading ? 'rgba(255,255,255,0.05)' : 'linear-gradient(135deg, var(--primary), var(--secondary))',
                            color: '#fff', fontWeight: 950, fontSize: '14px', letterSpacing: '0.1em',
                            cursor: isLoading ? 'not-allowed' : 'pointer',
                            boxShadow: isLoading ? 'none' : '0 10px 40px rgba(168, 85, 247, 0.3)', transition: 'all 0.3s ease',
                        }}>
                            {isLoading ? 'PROCESSING MISSION INTEL...' : 'GENERATE TACTICAL BRIEFING →'}
                        </button>

                        {briefing && (
                            <div className="glass reveal" style={{ marginTop: '4rem', padding: '3.5rem', borderRadius: '45px', background: 'linear-gradient(135deg, rgba(34,197,94,0.05) 0%, transparent 100%)', borderTop: '1px solid rgba(34,197,94,0.1)', width: '100%' }}>
                                <div className="flex items-center gap-4" style={{ marginBottom: '2.5rem' }}>
                                    <div style={{ width: '10px', height: '10px', background: '#22c55e', borderRadius: '2px' }}></div>
                                    <span style={{ fontSize: '11px', fontWeight: 950, color: '#22c55e', letterSpacing: '0.3em', textTransform: 'uppercase' }}>Strategic Resolution Active</span>
                                </div>
                                <div className="briefing-content" style={{ fontSize: '1.2rem', color: '#eee', lineHeight: 1.8 }}>
                                    <ReactMarkdown>{briefing}</ReactMarkdown>
                                </div>
                            </div>
                        )}
                    </section>
                </>
            )}
        </div>
    );
}

'use client';

import { useState } from 'react';
import { getTacticalStrategy } from '@/lib/actions';
import ReactMarkdown from 'react-markdown';

interface PredictedMatchData {
    predictedPts: number;
    predictedAuto: number;
    predictedTele: number;
    predictedTower: number;
    sampleSize: number;
    variance?: number;
}

interface ActualMatchData {
    autoFuel: number;
    teleFuel: number;
    autoClimb: string;
    teleClimb: string;
    towerPts: number;
    autoMoved: boolean;
    mechFailure: boolean;
    defenderRating: number;
    notes: string;
    scoutedBy: string;
}

interface TeamProfile {
    teamKey: string;
    teamNum: string;
    avgAutoFuel: string;
    avgTeleopFuel: string;
    avgFuel: string;
    avgTowerPts: string;
    bestTowerLevel: string;
    autoMobility: string;
    autoFuel: string;
    towerRate: string;
    avgDefense: string;
    hubControl: string;
    trenchCapable: string;
    failures: number;
    notes: string;
    predicted: PredictedMatchData;
    actual: ActualMatchData | null;
    pit?: {
        drivebase?: string;
        climb?: string;
        hopperCapacity?: number | null;
        trench?: string;
        bump?: string;
        canLob?: string;
        turret?: string;
        shiftTracking?: string;
        pickupFloor?: string;
        pickupOutpost?: string;
        autoClimb?: string;
        robotQuality?: number;
        weightLbs?: number | null;
        heightIn?: number | null;
        otherNotes?: string;
    } | null;
}

interface TBAAllianceBreakdown {
    autoPoints: number | null;
    teleopPoints: number | null;
    endgamePoints: number | null;
    fuelPoints: number | null;
    autoFuelPoints: number | null;
    teleopFuelPoints: number | null;
    towerEndgamePoints: number | null;
    rp: number | null;
}

interface TBAResult {
    redScore: number;
    blueScore: number;
    winner: 'red' | 'blue' | 'tie';
    red: TBAAllianceBreakdown;
    blue: TBAAllianceBreakdown;
}

interface Props {
    matchKey: string;
    eventKey: string;
    redProfiles: TeamProfile[];
    blueProfiles: TeamProfile[];
    isPlayed: boolean;
    tbaResult: TBAResult | null;
    redPredicted: number;
    bluePredicted: number;
}

const CLIMB_LABEL: Record<string, string> = { Level3: 'L3 ', Level2: 'L2', Level1: 'L1', 'No Attempt': '—', None: '—' };

function AllianceBreakdown({
    profiles,
    alliance,
    tba,
    totalScore,
    eventKey,
}: {
    profiles: TeamProfile[];
    alliance: 'red' | 'blue';
    tba: TBAAllianceBreakdown | null;
    totalScore: number;
    eventKey: string;
}) {
    const color = alliance === 'red' ? '#ef4444' : '#3b82f6';
    const bgWin = alliance === 'red' ? 'rgba(239,68,68,0.07)' : 'rgba(59,130,246,0.07)';

    // Sum up what scouts recorded for this alliance in this match
    const scoutedAutoFuel = profiles.reduce((s, p) => s + (p.actual?.autoFuel ?? 0), 0);
    const scoutedTeleFuel = profiles.reduce((s, p) => s + (p.actual?.teleFuel ?? 0), 0);
    const scoutedTowerPts = profiles.reduce((s, p) => s + (p.actual?.towerPts ?? 0), 0);

    // Official fuel pts from TBA (auto + tele fuel combined)
    const tbaTotalFuelPts = (tba?.fuelPoints ?? ((tba?.autoFuelPoints ?? 0) + (tba?.teleopFuelPoints ?? 0)));
    // Tower pts are fixed (10/20/30) — don't scale those
    const tbaNonTowerScore = totalScore - scoutedTowerPts;
    const scoutedNonTowerPts = scoutedAutoFuel + scoutedTeleFuel;

    // Scale factor: if scouts overcounted fuel, compress each robot's fuel proportionally
    // so that scaled fuel totals + tower pts = TBA total score
    const fuelScaleFactor = (scoutedNonTowerPts > 0 && tbaNonTowerScore > 0)
        ? Math.min(1, tbaNonTowerScore / scoutedNonTowerPts)
        : 1;
    const isScaled = Math.abs(fuelScaleFactor - 1) > 0.02; // only show scale indicator if >2% off

    // Human player contribution = TBA fuel pts − scaled robot fuel
    const scaledTotalFuel = scoutedNonTowerPts * fuelScaleFactor;
    const humanPlayerFuel = Math.max(0, tbaTotalFuelPts - scaledTotalFuel);

    const scoutCoverage = profiles.filter(p => p.actual !== null).length;

    return (
        <div style={{ background: bgWin, borderRadius: '30px', padding: '2rem', border: `1px solid ${color}22` }}>
            {/* Header */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
                <div>
                    <p style={{ fontSize: '9px', fontWeight: 950, color, textTransform: 'uppercase', letterSpacing: '0.2em' }}>{alliance} alliance</p>
                    <p style={{ fontSize: '3rem', fontWeight: 950, fontStyle: 'italic', color, lineHeight: 1 }}>{totalScore}</p>
                    {tba?.rp != null && <p style={{ fontSize: '9px', color: '#888', fontWeight: 700 }}>{tba.rp} RP</p>}
                </div>
                <div style={{ textAlign: 'right' }}>
                    {scoutCoverage < profiles.length && (
                        <p style={{ fontSize: '9px', color: '#eab308', fontWeight: 900 }}>⚠ {scoutCoverage}/{profiles.length} SCOUTED</p>
                    )}
                    {isScaled && (
                        <p style={{ fontSize: '9px', color: '#a855f7', fontWeight: 900 }}>⚖ SCALED ×{fuelScaleFactor.toFixed(2)}</p>
                    )}
                    {tba && (
                        <div style={{ fontSize: '9px', color: '#666', lineHeight: 1.6 }}>
                            {tba.autoPoints != null && <div>Auto: <span style={{ color: '#aaa' }}>{tba.autoPoints}pts</span></div>}
                            {tba.teleopPoints != null && <div>Teleop: <span style={{ color: '#aaa' }}>{tba.teleopPoints}pts</span></div>}
                            {tba.endgamePoints != null && <div>Endgame: <span style={{ color: '#aaa' }}>{tba.endgamePoints}pts</span></div>}
                        </div>
                    )}
                </div>
            </div>

            {/* Per-robot rows */}
            <div style={{ display: 'grid', gap: '0.75rem', marginBottom: '1.25rem' }}>
                {profiles.map(p => {
                    const a = p.actual;
                    const rawFuel = a ? a.autoFuel + a.teleFuel : 0;
                    const scaledFuel = Math.round(rawFuel * fuelScaleFactor);
                    const robotTotal = a ? scaledFuel + a.towerPts : null;
                    const rawTotal = a ? rawFuel + a.towerPts : null;
                    const pct = (robotTotal != null && totalScore > 0)
                        ? ((robotTotal / totalScore) * 100).toFixed(0)
                        : null;
                    return (
                        <a key={p.teamKey} href={`/event/${eventKey}/team/${p.teamKey}`}
                            style={{ textDecoration: 'none', color: 'inherit' }}>
                            <div style={{ background: 'rgba(0,0,0,0.3)', borderRadius: '18px', padding: '1rem 1.25rem', border: `1px solid ${a ? color + '33' : 'rgba(255,255,255,0.04)'}` }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: a ? '0.75rem' : 0 }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
                                        <span style={{ fontSize: '1.25rem', fontWeight: 950, color }}>{p.teamNum}</span>
                                        {a?.mechFailure && <span style={{ fontSize: '8px', background: 'rgba(239,68,68,0.2)', color: '#ef4444', padding: '0.15rem 0.4rem', borderRadius: '5px', fontWeight: 900 }}>FAIL</span>}
                                        {a?.defenderRating && a.defenderRating > 0 && <span style={{ fontSize: '8px', background: 'rgba(234,179,8,0.15)', color: '#eab308', padding: '0.15rem 0.4rem', borderRadius: '5px', fontWeight: 900 }}>DEF {a.defenderRating}</span>}
                                        {!a && <span style={{ fontSize: '8px', color: '#444', fontWeight: 700 }}>not scouted this match</span>}
                                    </div>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                                        {robotTotal != null && (
                                            <span style={{ fontSize: '1.1rem', fontWeight: 950, color: '#fff', fontFamily: 'monospace' }}>
                                                {robotTotal}pts
                                            </span>
                                        )}
                                        {isScaled && rawTotal != null && rawTotal !== robotTotal && (
                                            <span style={{ fontSize: '8px', color: '#555', fontFamily: 'monospace' }}>({rawTotal} raw)</span>
                                        )}
                                        {/* Predicted score + diff */}
                                        <span style={{ fontSize: '8px', color: '#666', fontFamily: 'monospace' }}>
                                            pred <span style={{ color: '#a855f7' }}>{p.predicted.predictedPts}</span>
                                            {robotTotal != null && (
                                                <span style={{ color: Math.abs(robotTotal - p.predicted.predictedPts) < p.predicted.predictedPts * 0.2 ? '#22c55e' : '#eab308', marginLeft: '0.2rem' }}>
                                                    ({robotTotal >= p.predicted.predictedPts ? '+' : ''}{robotTotal - p.predicted.predictedPts})
                                                </span>
                                            )}
                                        </span>
                                        {pct != null && (
                                            <span style={{ fontSize: '9px', color: '#666', fontWeight: 700 }}>{pct}%</span>
                                        )}
                                    </div>
                                </div>

                                {a && (
                                    <>
                                        {/* Stat pills */}
                                        <div style={{ display: 'flex', gap: '0.4rem', flexWrap: 'wrap', marginBottom: '0.5rem' }}>
                                            <StatPill label="AUTO" value={`${Math.round(a.autoFuel * fuelScaleFactor)}⛽${isScaled ? ` (${a.autoFuel})` : ''}`} color={color} />
                                            <StatPill label="TELE" value={`${Math.round(a.teleFuel * fuelScaleFactor)}⛽${isScaled ? ` (${a.teleFuel})` : ''}`} color={color} />
                                            <StatPill label="TOWER" value={CLIMB_LABEL[a.teleClimb] ?? '—'} color={a.towerPts > 0 ? '#eab308' : '#444'} />
                                            {a.autoMoved && <StatPill label="" value="✓ AUTO MOV" color="#22c55e" />}
                                        </div>

                                        {/* Contribution bar — scaled pts vs TBA total */}
                                        {totalScore > 0 && robotTotal != null && (
                                            <div style={{ height: '4px', background: 'rgba(255,255,255,0.05)', borderRadius: '2px' }}>
                                                <div style={{ height: '100%', borderRadius: '2px', background: color, width: `${Math.min(100, (robotTotal / totalScore) * 100)}%`, transition: 'width 0.5s ease' }} />
                                            </div>
                                        )}

                                        {/* Notes */}
                                        {a.notes && (
                                            <p style={{ fontSize: '0.7rem', color: '#666', fontStyle: 'italic', marginTop: '0.4rem', lineHeight: 1.4 }}>
                                                &ldquo;{a.notes}&rdquo;
                                                <span style={{ color: '#444', marginLeft: '0.4rem' }}>— {a.scoutedBy}</span>
                                            </p>
                                        )}
                                    </>
                                )}

                                {/* Avg + predicted fallback for unscouted */}
                                {!a && (
                                    <div style={{ display: 'flex', gap: '0.4rem', flexWrap: 'wrap' }}>
                                        <StatPill label="PRED" value={`${p.predicted.predictedPts}pts`} color="#a855f7" />
                                        <StatPill label="AVG AUTO" value={p.avgAutoFuel} color="#555" />
                                        <StatPill label="AVG TELE" value={p.avgTeleopFuel} color="#555" />
                                        <StatPill label="AVG TWR" value={p.avgTowerPts} color="#555" />
                                        {p.predicted.sampleSize > 0 && <StatPill label="n=" value={String(p.predicted.sampleSize)} color="#333" />}
                                    </div>
                                )}
                            </div>
                        </a>
                    );
                })}
            </div>

            {/* Human Player contribution row */}
            {scoutCoverage > 0 && humanPlayerFuel > 0 && (
                <div style={{ background: 'rgba(6,182,212,0.07)', borderRadius: '14px', padding: '0.75rem 1.25rem', border: '1px solid rgba(6,182,212,0.15)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
                        <span style={{ fontSize: '0.9rem' }}></span>
                        <div>
                            <p style={{ fontSize: '9px', fontWeight: 950, color: '#06b6d4', textTransform: 'uppercase', letterSpacing: '0.1em' }}>Human Player</p>
                            <p style={{ fontSize: '8px', color: '#444' }}>TBA fuel − scouted robot fuel</p>
                        </div>
                    </div>
                    <div style={{ textAlign: 'right' }}>
                        <p style={{ fontSize: '1.1rem', fontWeight: 950, color: '#06b6d4', fontFamily: 'monospace' }}>~{humanPlayerFuel}pts</p>
                        <p style={{ fontSize: '8px', color: '#444' }}>{((humanPlayerFuel / totalScore) * 100).toFixed(0)}% of total</p>
                    </div>
                </div>
            )}

            {/* Scouted total vs TBA */}
            {scoutCoverage > 0 && tbaTotalFuelPts > 0 && (
                <div style={{ marginTop: '0.75rem', padding: '0.5rem 1rem', background: 'rgba(255,255,255,0.02)', borderRadius: '10px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <span style={{ fontSize: '8px', fontWeight: 900, color: '#444', textTransform: 'uppercase' }}>Fuel accuracy</span>
                    <span style={{ fontSize: '8px', fontWeight: 950, color: Math.abs((scoutedAutoFuel + scoutedTeleFuel) - tbaTotalFuelPts) < tbaTotalFuelPts * 0.15 ? '#22c55e' : '#eab308' }}>
                        {scoutedAutoFuel + scoutedTeleFuel} scouted · {tbaTotalFuelPts} TBA fuel
                        {' '}({(scoutedAutoFuel + scoutedTeleFuel) >= tbaTotalFuelPts ? '+' : ''}{(scoutedAutoFuel + scoutedTeleFuel) - tbaTotalFuelPts} diff)
                    </span>
                </div>
            )}
        </div>
    );
}

function StatPill({ label, value, color }: { label: string; value: string; color: string }) {
    return (
        <span style={{ fontSize: '8px', fontWeight: 900, background: `${color}18`, color, padding: '0.2rem 0.5rem', borderRadius: '6px', whiteSpace: 'nowrap' }}>
            {label && <span style={{ opacity: 0.7, marginRight: '0.25rem' }}>{label}</span>}
            {value}
        </span>
    );
}

export default function MatchTacticalInterface({ matchKey, eventKey, redProfiles, blueProfiles, isPlayed, tbaResult, redPredicted, bluePredicted }: Props) {
    const [selectedAlliance, setSelectedAlliance] = useState<'red' | 'blue'>('red');
    const [manualNotes, setManualNotes] = useState<Record<string, string>>({});
    const [briefing, setBriefing] = useState<string | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [view, setView] = useState<'breakdown' | 'strategy'>(isPlayed ? 'breakdown' : 'strategy');

    const activeProfiles = selectedAlliance === 'red' ? redProfiles : blueProfiles;
    const opponentProfiles = selectedAlliance === 'red' ? blueProfiles : redProfiles;

    const handleGenerate = async () => {
        setIsLoading(true);
        setBriefing(null);
        const updatedAllianceData = activeProfiles.map(p => ({
            ...p,
            notes: manualNotes[p.teamKey] ? `${p.notes} [OVERRIDE: ${manualNotes[p.teamKey]}]` : p.notes
        }));
        const result = await getTacticalStrategy(matchKey, selectedAlliance, updatedAllianceData, opponentProfiles);
        setBriefing(result);
        setIsLoading(false);
    };

    return (
        <div style={{ display: 'grid', gap: '3rem' }}>

            {/* View toggle for played matches */}
            {isPlayed && (
                <section className="reveal">
                    <div className="glass" style={{ padding: '1rem', borderRadius: '20px', display: 'flex', gap: '0.5rem', width: 'fit-content' }}>
                        {(['breakdown', 'strategy'] as const).map(v => (
                            <button key={v} onClick={() => setView(v)} style={{
                                padding: '0.6rem 1.5rem', borderRadius: '12px', border: 'none', fontWeight: 950, fontSize: '11px', cursor: 'pointer', letterSpacing: '0.05em', textTransform: 'uppercase',
                                background: view === v ? 'var(--primary)' : 'transparent',
                                color: view === v ? '#000' : '#555',
                            }}>
                                {v === 'breakdown' ? ' Match Breakdown' : ' Strategy View'}
                            </button>
                        ))}
                    </div>
                </section>
            )}

            {/* ── PLAYED MATCH BREAKDOWN ── */}
            {isPlayed && view === 'breakdown' && tbaResult && (
                <section className="reveal delay-1">
                    {/* Scoreboard */}
                    <div className="glass" style={{ padding: '1.5rem 2rem', borderRadius: '25px', marginBottom: '2rem', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '2rem' }}>
                        <div style={{ textAlign: 'center' }}>
                            <p style={{ fontSize: '9px', fontWeight: 950, color: '#ef4444', letterSpacing: '0.2em', textTransform: 'uppercase' }}>Red Alliance</p>
                            <p style={{ fontSize: '3.5rem', fontWeight: 950, fontStyle: 'italic', color: tbaResult.winner === 'red' ? '#ef4444' : '#888', lineHeight: 1 }}>{tbaResult.redScore}</p>
                            <p style={{ fontSize: '9px', color: '#555', fontWeight: 700 }}>
                                pred <span style={{ color: Math.abs(redPredicted - tbaResult.redScore) < tbaResult.redScore * 0.15 ? '#22c55e' : '#eab308' }}>{redPredicted}</span>
                                {' '}<span style={{ color: '#444' }}>({redPredicted >= tbaResult.redScore ? '+' : ''}{redPredicted - tbaResult.redScore})</span>
                            </p>
                        </div>
                        <div style={{ textAlign: 'center' }}>
                            <p style={{ fontSize: '1rem', fontWeight: 950, color: '#444' }}>VS</p>
                            <p style={{ fontSize: '9px', fontWeight: 950, color: tbaResult.winner === 'tie' ? '#eab308' : tbaResult.winner === 'red' ? '#ef4444' : '#3b82f6', marginTop: '0.25rem', textTransform: 'uppercase', letterSpacing: '0.1em' }}>
                                {tbaResult.winner === 'tie' ? '⚖ TIE' : `${tbaResult.winner.toUpperCase()} WINS`}
                            </p>
                            <p style={{ fontSize: '8px', color: '#333', marginTop: '0.5rem' }}>PRED {redPredicted} – {bluePredicted}</p>
                        </div>
                        <div style={{ textAlign: 'center' }}>
                            <p style={{ fontSize: '9px', fontWeight: 950, color: '#3b82f6', letterSpacing: '0.2em', textTransform: 'uppercase' }}>Blue Alliance</p>
                            <p style={{ fontSize: '3.5rem', fontWeight: 950, fontStyle: 'italic', color: tbaResult.winner === 'blue' ? '#3b82f6' : '#888', lineHeight: 1 }}>{tbaResult.blueScore}</p>
                            <p style={{ fontSize: '9px', color: '#555', fontWeight: 700 }}>
                                pred <span style={{ color: Math.abs(bluePredicted - tbaResult.blueScore) < tbaResult.blueScore * 0.15 ? '#22c55e' : '#eab308' }}>{bluePredicted}</span>
                                {' '}<span style={{ color: '#444' }}>({bluePredicted >= tbaResult.blueScore ? '+' : ''}{bluePredicted - tbaResult.blueScore})</span>
                            </p>
                        </div>
                    </div>

                    {/* Alliance breakdowns side by side */}
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(340px, 1fr))', gap: '1.5rem' }}>
                        <AllianceBreakdown profiles={redProfiles} alliance="red" tba={tbaResult.red} totalScore={tbaResult.redScore} eventKey={eventKey} />
                        <AllianceBreakdown profiles={blueProfiles} alliance="blue" tba={tbaResult.blue} totalScore={tbaResult.blueScore} eventKey={eventKey} />
                    </div>
                </section>
            )}

            {/* ── STRATEGY VIEW (upcoming OR toggle on played) ── */}
            {(!isPlayed || view === 'strategy') && (
                <>
                    {/* Alliance Control Center */}
                    <section className="reveal delay-1">
                        <div className="glass" style={{ padding: '2rem', borderRadius: '40px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <div>
                                <p style={{ fontSize: '10px', fontWeight: 950, color: '#888', textTransform: 'uppercase', letterSpacing: '0.2em', marginBottom: '0.5rem' }}>Tactical Focus</p>
                                <h2 style={{ fontSize: '1.5rem', fontWeight: 950, fontStyle: 'italic', textTransform: 'uppercase' }}>Alliance Selection</h2>
                            </div>
                            <div className="flex gap-4" style={{ background: 'rgba(255,255,255,0.03)', padding: '0.5rem', borderRadius: '100px', border: '1px solid rgba(255,255,255,0.05)' }}>
                                {(['red', 'blue'] as const).map(a => (
                                    <button key={a} onClick={() => setSelectedAlliance(a)} style={{
                                        padding: '0.75rem 2rem', borderRadius: '100px', border: 'none',
                                        background: selectedAlliance === a ? (a === 'red' ? '#ef4444' : '#3b82f6') : 'transparent',
                                        color: selectedAlliance === a ? '#fff' : '#444',
                                        fontWeight: 950, fontSize: '12px', cursor: 'pointer', transition: 'all 0.3s ease', textTransform: 'uppercase',
                                    }}>{a} Alliance</button>
                                ))}
                            </div>
                        </div>
                    </section>

                    {/* Team Scoring Dashboard */}
                    <section className="reveal delay-2">
                        <div className="flex items-center gap-4" style={{ marginBottom: '2rem' }}>
                            <div style={{ width: '8px', height: '8px', borderRadius: '50%', background: selectedAlliance === 'red' ? '#ef4444' : '#3b82f6', boxShadow: `0 0 10px ${selectedAlliance === 'red' ? '#ef4444' : '#3b82f6'}` }}></div>
                            <h3 style={{ fontSize: '11px', fontWeight: 950, letterSpacing: '0.3em', textTransform: 'uppercase', color: '#444' }}>Allied Unit Readiness</h3>
                            <div style={{ marginLeft: 'auto', display: 'flex', gap: '1.5rem' }}>
                                <div style={{ textAlign: 'center' }}>
                                    <p style={{ fontSize: '8px', fontWeight: 900, color: '#ef4444', textTransform: 'uppercase' }}>Red Pred</p>
                                    <p style={{ fontSize: '1rem', fontWeight: 950, color: '#ef4444', fontFamily: 'monospace' }}>{redPredicted}</p>
                                </div>
                                <div style={{ fontSize: '10px', color: '#333', alignSelf: 'center' }}>vs</div>
                                <div style={{ textAlign: 'center' }}>
                                    <p style={{ fontSize: '8px', fontWeight: 900, color: '#3b82f6', textTransform: 'uppercase' }}>Blue Pred</p>
                                    <p style={{ fontSize: '1rem', fontWeight: 950, color: '#3b82f6', fontFamily: 'monospace' }}>{bluePredicted}</p>
                                </div>
                            </div>
                        </div>

                        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(320px, 1fr))', gap: '1.5rem' }}>
                            {activeProfiles.map((p) => (
                                <div key={p.teamKey} className="glass" style={{ padding: '2rem', borderRadius: '35px', borderLeft: `4px solid ${selectedAlliance === 'red' ? '#ef4444' : '#3b82f6'}33` }}>
                                    <div className="flex justify-between items-start" style={{ marginBottom: '1.5rem' }}>
                                        <div>
                                            <h4 style={{ fontSize: '2.5rem', fontWeight: 950, fontStyle: 'italic', color: '#fff', lineHeight: 1 }}>{p.teamNum}</h4>
                                            <p style={{ fontSize: '9px', fontWeight: 950, color: '#888', textTransform: 'uppercase', letterSpacing: '0.1em' }}>Tactical Unit</p>
                                        </div>
                                        <div style={{ textAlign: 'right' }}>
                                            <div style={{ fontSize: '1.25rem', fontWeight: 950, color: '#a855f7', fontFamily: 'monospace', lineHeight: 1 }}>
                                                {p.predicted.predictedPts}pts
                                            </div>
                                            <p style={{ fontSize: '8px', color: '#555', fontWeight: 700 }}>
                                                {p.predicted.predictedAuto}a + {p.predicted.predictedTele}t + {p.predicted.predictedTower}e
                                                {p.predicted.sampleSize > 0 && <span style={{ color: '#333', marginLeft: '0.25rem' }}>n={p.predicted.sampleSize}</span>}
                                            </p>
                                            <p style={{ fontSize: '9px', fontWeight: 950, color: '#aaa', marginTop: '0.25rem' }}>HUB: {p.hubControl?.toUpperCase()}</p>
                                            {p.pit && <span style={{ fontSize: '8px', fontWeight: 950, background: 'rgba(168,85,247,0.2)', color: '#a855f7', padding: '0.15rem 0.4rem', borderRadius: '6px', marginTop: '0.3rem', display: 'inline-block' }}>PIT ✓</span>}
                                        </div>
                                    </div>

                                    <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '0.75rem', marginBottom: '1rem' }}>
                                        {[
                                            { label: 'AUTO FUEL', val: p.avgAutoFuel },
                                            { label: 'TELE FUEL', val: p.avgTeleopFuel },
                                            { label: 'TOWER PTS', val: p.avgTowerPts },
                                            { label: 'TOWER %', val: `${p.towerRate}%` },
                                            { label: 'TRENCH', val: p.trenchCapable, color: p.trenchCapable === 'Yes' ? '#22c55e' : '#666' },
                                            { label: 'DEFENSE', val: p.avgDefense },
                                        ].map(({ label, val, color }) => (
                                            <div key={label} style={{ background: 'rgba(255,255,255,0.02)', padding: '0.75rem', borderRadius: '15px', textAlign: 'center' }}>
                                                <p style={{ fontSize: '7px', fontWeight: 950, color: '#888' }}>{label}</p>
                                                <p style={{ fontSize: '1.25rem', fontWeight: 950, color: color ?? '#fff' }}>{val}</p>
                                            </div>
                                        ))}
                                    </div>

                                    {p.pit && (
                                        <div style={{ marginBottom: '1rem', padding: '0.75rem', background: 'rgba(168,85,247,0.06)', borderRadius: '12px', border: '1px solid rgba(168,85,247,0.15)' }}>
                                            <p style={{ fontSize: '8px', fontWeight: 950, color: '#a855f7', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '0.5rem' }}>Pit Intel</p>
                                            <div style={{ display: 'flex', gap: '0.4rem', flexWrap: 'wrap' }}>
                                                {p.pit.drivebase && <StatPill label="" value={p.pit.drivebase} color="#888" />}
                                                {p.pit.climb && p.pit.climb !== 'No Attempt' && <StatPill label="Max" value={p.pit.climb} color="#eab308" />}
                                                {p.pit.hopperCapacity != null && <StatPill label="Hopper" value={String(p.pit.hopperCapacity)} color="#c084fc" />}
                                                {p.pit.turret === 'Yes' && <StatPill label="" value="Turret" color="#22c55e" />}
                                                {p.pit.canLob === 'Yes' && <StatPill label="" value="Lob" color="#06b6d4" />}
                                                {p.pit.robotQuality != null && <StatPill label="Quality" value={`${p.pit.robotQuality}/5`} color="#aaa" />}
                                            </div>
                                        </div>
                                    )}

                                    <div>
                                        <p style={{ fontSize: '8px', fontWeight: 950, color: selectedAlliance === 'red' ? '#ef4444' : '#3b82f6', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: '0.5rem' }}>Intelligence Overrides</p>
                                        <textarea
                                            placeholder="Enter field observations..."
                                            value={manualNotes[p.teamKey] || ''}
                                            onChange={(e) => setManualNotes({ ...manualNotes, [p.teamKey]: e.target.value })}
                                            style={{ width: '100%', height: '80px', background: 'rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.05)', borderRadius: '15px', padding: '1rem', color: '#ccc', fontSize: '11px', resize: 'none', fontFamily: 'inherit' }}
                                        />
                                    </div>
                                </div>
                            ))}
                        </div>
                    </section>

                    {/* AI Generation */}
                    <section className="reveal delay-3 flex flex-col items-center" style={{ marginTop: '2rem' }}>
                        <button onClick={handleGenerate} disabled={isLoading} className="generate-btn" style={{
                            padding: '1.5rem 4rem', borderRadius: '100px', border: 'none',
                            background: isLoading ? 'rgba(255,255,255,0.05)' : 'linear-gradient(135deg, var(--primary), var(--secondary))',
                            color: '#fff', fontWeight: 950, fontSize: '14px', letterSpacing: '0.1em',
                            cursor: isLoading ? 'not-allowed' : 'pointer',
                            boxShadow: isLoading ? 'none' : '0 10px 40px rgba(168, 85, 247, 0.3)', transition: 'all 0.3s ease',
                        }}>
                            {isLoading ? 'PROCESSING MISSION INTEL...' : 'GENERATE TACTICAL BRIEFING →'}
                        </button>

                        {briefing && (
                            <div className="glass reveal" style={{ marginTop: '4rem', padding: '3.5rem', borderRadius: '45px', background: 'linear-gradient(135deg, rgba(34,197,94,0.05) 0%, transparent 100%)', borderTop: '1px solid rgba(34,197,94,0.1)', width: '100%' }}>
                                <div className="flex items-center gap-4" style={{ marginBottom: '2.5rem' }}>
                                    <div style={{ width: '10px', height: '10px', background: '#22c55e', borderRadius: '2px' }}></div>
                                    <span style={{ fontSize: '11px', fontWeight: 950, color: '#22c55e', letterSpacing: '0.3em', textTransform: 'uppercase' }}>Strategic Resolution Active</span>
                                </div>
                                <div className="briefing-content" style={{ fontSize: '1.2rem', color: '#eee', lineHeight: 1.8 }}>
                                    <ReactMarkdown>{briefing}</ReactMarkdown>
                                </div>
                            </div>
                        )}
                    </section>
                </>
            )}
        </div>
    );
}

'use server';

import { getPool, sql } from './db';
import { generateMatchStrategy, generateTeamStrategy } from './ai';
import { ScoutReport, PitReport, StatboticsTeamEvent } from './types/scouting';

export async function saveScoutReport(report: Record<string, any>) {
    try {
        const pool = await getPool();

        // REBUILT 2026 — map form fields to frc6377MatchScouting columns
        const autoFuel: number     = Number(report.auto?.fuel ?? report.auto?.fuel_scored ?? 0);
        const teleFuel: number     = Number(report.tele?.fuel ?? report.tele?.fuel_scored ?? 0);
        // towerLevel from form → climb_level in DB
        const autoClimbLevel: string = report.auto?.towerLevel || report.auto?.climb_level || 'No Attempt';
        const teleClimbLevel: string = report.tele?.towerLevel || report.tele?.climb_level || 'No Attempt';
        const autoMoved: string    = (report.auto?.moved) ? 'Yes' : 'No';
        const mechFailure: string  = (report.mech_failure) ? 'Yes' : 'No';
        const defenderRating: number = Number(report.defender_rating) || 0;
        const otherNotes: string   = String(report.notes || report.other_notes || '').trim();

        const teamNum = String(report.team).replace('frc', '');
        const eventKey: string   = report.eventKey || '2026txcle';
        const matchKey: string   = report.match || '';
        const compLevel: string  = 'qm';
        const matchNumber        = parseInt(matchKey.split('_qm').pop() || '0', 10);
        const driverStation: string = report.driver_station || '';
        const scoutedBy: string  = report.scouter || 'Unknown';
        const primaryKey         = `${teamNum}-${matchKey}-${scoutedBy}`;

        await pool.request()
            .input('primary_key',      sql.NVarChar(100), primaryKey)
            .input('frc_team',         sql.NVarChar(10),  teamNum)
            .input('event_key',        sql.NVarChar(20),  eventKey)
            .input('match_key',        sql.NVarChar(50),  matchKey)
            .input('driver_station',   sql.NVarChar(10),  driverStation)
            .input('comp_level',       sql.NVarChar(5),   compLevel)
            .input('match_number',     sql.Int,           matchNumber)
            .input('auto_moved',       sql.NVarChar(5),   autoMoved)
            .input('auto_fuel_scored', sql.Int,           autoFuel)
            .input('auto_fuel_missed', sql.Int,           0)
            .input('auto_climb_level', sql.NVarChar(20),  autoClimbLevel)
            .input('auto_climb_position', sql.NVarChar(20), 'No Attempt')
            .input('tele_fuel_scored', sql.Int,           teleFuel)
            .input('tele_fuel_missed', sql.Int,           0)
            .input('tele_human_fuel_scored', sql.Int,     0)
            .input('tele_human_fuel_missed', sql.Int,     0)
            .input('tele_climb_level', sql.NVarChar(20),  teleClimbLevel)
            .input('tele_climb_position', sql.NVarChar(20), 'No Attempt')
            .input('defender_rating',  sql.Int,           defenderRating)
            .input('mech_failure',     sql.NVarChar(5),   mechFailure)
            .input('scouted_by',       sql.NVarChar(100), scoutedBy)
            .query(`
                MERGE frc6377MatchScouting AS target
                USING (SELECT @primary_key AS primary_key) AS source
                    ON target.primary_key = source.primary_key
                WHEN NOT MATCHED THEN
                    INSERT (
                        primary_key, frc_team, event_key, match_key, driver_station,
                        comp_level, match_number, auto_moved, auto_fuel_scored, auto_fuel_missed,
                        auto_climb_level, auto_climb_position,
                        tele_fuel_scored, tele_fuel_missed, tele_human_fuel_scored, tele_human_fuel_missed,
                        tele_climb_level, tele_climb_position,
                        defender_rating, mech_failure, scouted_by
                    )
                    VALUES (
                        @primary_key, @frc_team, @event_key, @match_key, @driver_station,
                        @comp_level, @match_number, @auto_moved, @auto_fuel_scored, @auto_fuel_missed,
                        @auto_climb_level, @auto_climb_position,
                        @tele_fuel_scored, @tele_fuel_missed, @tele_human_fuel_scored, @tele_human_fuel_missed,
                        @tele_climb_level, @tele_climb_position,
                        @defender_rating, @mech_failure, @scouted_by
                    )
                WHEN MATCHED THEN
                    UPDATE SET
                        auto_moved = @auto_moved,
                        auto_fuel_scored = @auto_fuel_scored,
                        auto_climb_level = @auto_climb_level,
                        tele_fuel_scored = @tele_fuel_scored,
                        tele_climb_level = @tele_climb_level,
                        defender_rating  = @defender_rating,
                        mech_failure     = @mech_failure,
                        scouted_by       = @scouted_by;
            `);

        // Save notes to frc6377MatchScoutingPrivate (the dedicated notes table)
        const privateKey = `${teamNum}-${matchKey}-${driverStation}-${scoutedBy}`;
        await pool.request()
            .input('private_key',    sql.NVarChar(200), privateKey)
            .input('frc_team',       sql.NVarChar(10),  teamNum)
            .input('event_key',      sql.NVarChar(20),  eventKey)
            .input('match_key',      sql.NVarChar(50),  matchKey)
            .input('driver_station', sql.NVarChar(10),  driverStation)
            .input('comp_level',     sql.NVarChar(5),   compLevel)
            .input('match_number',   sql.Int,           matchNumber)
            .input('scouted_by',     sql.NVarChar(100), scoutedBy)
            .input('other_notes',    sql.NVarChar(4000), otherNotes)
            .query(`
                MERGE frc6377MatchScoutingPrivate AS target
                USING (SELECT @private_key AS primary_key) AS source
                    ON target.primary_key = source.primary_key
                WHEN NOT MATCHED THEN
                    INSERT (primary_key, frc_team, event_key, match_key, driver_station, comp_level, match_number, scouted_by, other_notes)
                    VALUES (@private_key, @frc_team, @event_key, @match_key, @driver_station, @comp_level, @match_number, @scouted_by, @other_notes)
                WHEN MATCHED THEN
                    UPDATE SET other_notes = @other_notes, scouted_by = @scouted_by;
            `);

        return { success: true };
    } catch (e) {
        console.error('[DB] Failed to save report:', e);
        return { success: false, error: String(e) };
    }
}

export async function savePitReport(report: Record<string, unknown>) {
    try {
        const pool = await getPool();
        const teamNum   = String(report.team ?? '').replace('frc', '');
        const eventKey  = String(report.eventKey ?? '2026txcle');
        const scoutedBy = String(report.scouter ?? 'Unknown');
        const primaryKey = `${eventKey}-${teamNum}`;

        const n = (v: unknown) => (v != null && v !== '' ? Number(v) : null);
        const s = (v: unknown) => String(v ?? '').trim();

        await pool.request()
            .input('primary_key',         sql.NVarChar(100), primaryKey)
            .input('frc_team',            sql.NVarChar(10),  teamNum)
            .input('event_key',           sql.NVarChar(20),  eventKey)
            .input('scouted_by',          sql.NVarChar(100), scoutedBy)
            .input('weight_lbs',          sql.Float,         n(report.weight_lbs))
            .input('height_in',           sql.Float,         n(report.height_in))
            .input('width_in',            sql.Float,         n(report.width_in))
            .input('length_in',           sql.Float,         n(report.length_in))
            .input('drivebase',           sql.NVarChar(50),  s(report.drivebase))
            .input('code_language',       sql.NVarChar(50),  s(report.code_language))
            .input('turret',              sql.NVarChar(10),  s(report.turret))
            .input('climb',               sql.NVarChar(20),  s(report.climb))
            .input('climb_position_1',    sql.NVarChar(50),  s(report.climb_position_1))
            .input('climb_position_2',    sql.NVarChar(50),  s(report.climb_position_2))
            .input('climb_partners',      sql.Int,           n(report.climb_partners) ?? 0)
            .input('auto_climb',          sql.NVarChar(10),  s(report.auto_climb))
            .input('auto_pref_start',     sql.NVarChar(50),  s(report.auto_pref_start))
            .input('auto_pref_pickup',    sql.NVarChar(10),  s(report.auto_pref_pickup))
            .input('hopper_capacity',     sql.Int,           n(report.hopper_capacity))
            .input('hopper_length_in',    sql.Float,         n(report.hopper_length_in))
            .input('hopper_width_in',     sql.Float,         n(report.hopper_width_in))
            .input('hopper_height_in',    sql.Float,         n(report.hopper_height_in))
            .input('trench',              sql.NVarChar(10),  s(report.trench))
            .input('bump',                sql.NVarChar(10),  s(report.bump))
            .input('bump_practice',       sql.NVarChar(10),  s(report.bump_practice))
            .input('can_lob',             sql.NVarChar(10),  s(report.can_lob))
            .input('can_doze',            sql.NVarChar(10),  s(report.can_doze))
            .input('pickup_floor',        sql.NVarChar(10),  s(report.pickup_floor))
            .input('pickup_outpost',      sql.NVarChar(10),  s(report.pickup_outpost))
            .input('preferred_ds',        sql.NVarChar(20),  s(report.preferred_ds))
            .input('shift_tracking',      sql.NVarChar(10),  s(report.shift_tracking))
            .input('kitbot',              sql.NVarChar(50),  s(report.kitbot))
            .input('kitbot_modified',     sql.NVarChar(200), s(report.kitbot_modified))
            .input('human_player',        sql.NVarChar(100), s(report.human_player))
            .input('human_player_height', sql.NVarChar(20),  s(report.human_player_height))
            .input('robot_quality',       sql.Int,           n(report.robot_quality) ?? 0)
            .input('pit_quality',         sql.Int,           n(report.pit_quality) ?? 0)
            .input('other_notes',         sql.NVarChar(sql.MAX), s(report.other_notes))
            .input('robot_image_url',     sql.NVarChar(sql.MAX), s(report.robot_image_url))
            .query(`
                MERGE frc6377TeamScoutingPrivate AS target
                USING (SELECT @primary_key AS primary_key) AS source
                    ON target.primary_key = source.primary_key
                WHEN NOT MATCHED THEN INSERT (
                    primary_key, frc_team, event_key, scouted_by,
                    weight_lbs, height_in, width_in, length_in,
                    drivebase, code_language, turret,
                    climb, climb_position_1, climb_position_2, climb_partners, auto_climb,
                    auto_pref_start, auto_pref_pickup,
                    hopper_capacity, hopper_length_in, hopper_width_in, hopper_height_in,
                    trench, bump, bump_practice, can_lob, can_doze,
                    pickup_floor, pickup_outpost, preferred_ds, shift_tracking,
                    kitbot, kitbot_modified, human_player, human_player_height,
                    robot_quality, pit_quality, other_notes, robot_image_url
                ) VALUES (
                    @primary_key, @frc_team, @event_key, @scouted_by,
                    @weight_lbs, @height_in, @width_in, @length_in,
                    @drivebase, @code_language, @turret,
                    @climb, @climb_position_1, @climb_position_2, @climb_partners, @auto_climb,
                    @auto_pref_start, @auto_pref_pickup,
                    @hopper_capacity, @hopper_length_in, @hopper_width_in, @hopper_height_in,
                    @trench, @bump, @bump_practice, @can_lob, @can_doze,
                    @pickup_floor, @pickup_outpost, @preferred_ds, @shift_tracking,
                    @kitbot, @kitbot_modified, @human_player, @human_player_height,
                    @robot_quality, @pit_quality, @other_notes, @robot_image_url
                )
                WHEN MATCHED THEN UPDATE SET
                    scouted_by = @scouted_by,
                    weight_lbs = @weight_lbs, height_in = @height_in, width_in = @width_in, length_in = @length_in,
                    drivebase = @drivebase, code_language = @code_language, turret = @turret,
                    climb = @climb, climb_position_1 = @climb_position_1, climb_position_2 = @climb_position_2,
                    climb_partners = @climb_partners, auto_climb = @auto_climb,
                    auto_pref_start = @auto_pref_start, auto_pref_pickup = @auto_pref_pickup,
                    hopper_capacity = @hopper_capacity, hopper_length_in = @hopper_length_in,
                    hopper_width_in = @hopper_width_in, hopper_height_in = @hopper_height_in,
                    trench = @trench, bump = @bump, bump_practice = @bump_practice,
                    can_lob = @can_lob, can_doze = @can_doze,
                    pickup_floor = @pickup_floor, pickup_outpost = @pickup_outpost,
                    preferred_ds = @preferred_ds, shift_tracking = @shift_tracking,
                    kitbot = @kitbot, kitbot_modified = @kitbot_modified,
                    human_player = @human_player, human_player_height = @human_player_height,
                    robot_quality = @robot_quality, pit_quality = @pit_quality, other_notes = @other_notes,
                    robot_image_url = CASE WHEN @robot_image_url <> '' THEN @robot_image_url ELSE robot_image_url END;
            `);
        return { success: true };
    } catch (e) {
        console.error('[DB] Failed to save pit report:', e);
        return { success: false, error: String(e) };
    }
}

