export interface TeamExportRow {
    teamNumber: number;
    teamName: string;
    rank: number | null;
    wins: number;
    losses: number;
    ties: number;
    rankingPoints: number;
    ourEPA: number;
    sbEPA: number | null;
    matchesScouted: number;
    failureRate: number;
    consistencyScore: number;
    riskLevel: string;
    synergyScore: number;
    role: string;
    strengths: string[];
    allNotes: string[];
    // Pit scouting fields
    pitDrivebase: string;
    pitClimb: string;
    pitClimbPartners: number;
    pitAutoClimb: string;
    pitHopperCapacity: number | null;
    pitTrench: string;
    pitBump: string;
    pitCanLob: string;
    pitCanDoze: string;
    pitPickupFloor: string;
    pitPickupOutpost: string;
    pitKitbot: string;
    pitRobotQuality: number;
    pitPitQuality: number;
    pitNotes: string;
    // Raw match data (JSON string in CSV, array in JSON)
    matchData: Array<{
        matchKey: string;
        autoFuel: number;
        teleFuel: number;
        autoClimb: string;
        teleClimb: string;
        mechFailure: boolean;
        defenderRating: number;
        notes: string;
    }>;
}

/* eslint-disable @typescript-eslint/no-explicit-any */
export async function exportAllTeamsAction(eventKey: string): Promise<TeamExportRow[]> {
    try {
        const [
            { getMissionData, getEventTeamList, getAllPitReports },
            { getEventTeams },
            { getStatboticsEvent },
            { calculateTeamEPA },
            { calculateTeamReliability },
            { generatePickList },
        ] = await Promise.all([
            import('./data'),
            import('./tba'),
            import('./statbotics'),
            import('./spr'),
            import('./reliability'),
            import('./pickList'),
        ]);

        const [missionData, rosterList, statboticsData, pitReports] = await Promise.all([
             getMissionData(eventKey),
             getEventTeamList(eventKey),
             getStatboticsEvent(eventKey),
             getAllPitReports(eventKey),
         ]);

         const { reports } = missionData;
         const teamNameMap: Record<string, string> = {};
         rosterList.forEach(t => teamNameMap[t.teamKey] = t.name);

         const reliability = Array.from(new Set(reports.map(r => r.teamKey)))
             .map(tk => calculateTeamReliability(reports.filter(r => r.teamKey === tk)));

         const pickListData = generatePickList(reports, reliability);

         const allScoutedKeys = Array.from(new Set(reports.map((r) => r.teamKey)));
        const rosterKeys = new Set(rosterList.map((r) => r.teamKey));
        const allTeamKeys = [
            ...rosterList.map((r) => r.teamKey),
            ...allScoutedKeys.filter((k) => !rosterKeys.has(k)),
        ];

        return Array.from(new Set(allTeamKeys)).map(teamKey => {
            const teamNum = parseInt(teamKey.replace('frc', ''), 10);
            const teamReports = reports.filter((r) => r.teamKey === teamKey);
            const ourEPA = calculateTeamEPA(teamReports);

            const sbData = (statboticsData as StatboticsTeamEvent[]).find((s) => s.team === teamNum);
            const sbEPA = sbData?.epa?.breakdown?.total_points ?? null;

            const synergy = pickListData.find((p) => p.teamKey === teamKey);
            const pit = pitReports.find((p) => p.teamKey === teamKey);

            const matchNotes = teamReports.map((r) => r.data?.notes).filter((n): n is string => !!n);
            const allNotes = [
                ...(pit?.otherNotes ? [pit.otherNotes] : []),
                ...matchNotes,
            ];

            const matchData = teamReports.map((r) => ({
                matchKey: r.matchKey,
                autoFuel: r.data?.auto?.fuel_scored ?? 0,
                teleFuel: r.data?.teleop?.fuel_scored ?? 0,
                autoClimb: r.data?.auto?.climb_level ?? 'No Attempt',
                teleClimb: r.data?.teleop?.climb_level ?? 'No Attempt',
                mechFailure: !!r.data?.mech_failure,
                defenderRating: r.data?.defender_rating ?? 0,
                notes: r.data?.notes ?? '',
            }));

            const sbRecord = (sbData?.record?.qual || {}) as any;

            return {
                teamNumber: teamNum,
                teamName: teamNameMap[teamKey] || `Team ${teamNum}`,
                rank: sbRecord?.rank ?? null,
                wins: sbRecord?.wins ?? 0,
                losses: sbRecord?.losses ?? 0,
                ties: sbRecord?.ties ?? 0,
                rankingPoints: sbRecord?.rps ?? 0,
                ourEPA,
                sbEPA,
                matchesScouted: teamReports.length,
                failureRate: 0,
                consistencyScore: 50,
                riskLevel: 'medium',
                synergyScore: synergy?.synergyScore ?? 0,
                role: synergy?.role ?? 'balanced',
                strengths: synergy?.strengths ?? [],
                allNotes,
                pitDrivebase: pit?.drivebase ?? '',
                pitClimb: pit?.climb ?? '',
                pitClimbPartners: pit?.climbPartners ?? 0,
                pitAutoClimb: pit?.autoClimb ?? '',
                pitHopperCapacity: pit?.hopperCapacity ?? null,
                pitTrench: pit?.trench ?? '',
                pitBump: pit?.bump ?? '',
                pitCanLob: pit?.canLob ?? '',
                pitCanDoze: pit?.canDoze ?? '',
                pitPickupFloor: pit?.pickupFloor ?? '',
                pitPickupOutpost: pit?.pickupOutpost ?? '',
                pitKitbot: pit?.kitbot ?? '',
                pitRobotQuality: pit?.robotQuality ?? 0,
                pitPitQuality: pit?.pitQuality ?? 0,
                pitNotes: pit?.otherNotes ?? '',
                matchData,
            };
        }).sort((a, b) => {
            if (a.matchesScouted > 0 && b.matchesScouted === 0) return -1;
            if (a.matchesScouted === 0 && b.matchesScouted > 0) return 1;
            if (a.matchesScouted > 0) return b.ourEPA - a.ourEPA;
            return a.teamNumber - b.teamNumber;
        });
    } catch (e) {
        console.error('[Export] exportAllTeamsAction error:', e);
        return [];
    }
}
/* eslint-enable @typescript-eslint/no-explicit-any */

export async function getTeamStrategyAction(
    teamKey: string,
    nickname: string,
    reports: Record<string, unknown>[],
    pitReport?: Record<string, unknown>
) {
    if (!process.env.HACK_CLUB_AI_KEY) return 'Tactical link offline (Key Missing).';
    return await generateTeamStrategy(teamKey, nickname, reports, pitReport as unknown as PitReport);
}

export async function getTeamQuestionsAction(teamKey: string, teamData: Record<string, unknown>) {
    if (!process.env.HACK_CLUB_AI_KEY) return 'Question generation offline (Key Missing).';

    // Fetch our own team's performance data to provide synergy context
    let ourTeamData = null;
    try {
        const { loadEventReports, getPitReport } = await import('./data');
        const { analyzeTeamRole } = await import('./pickList');
        const { analyzeDefenseProfile } = await import('./defense');

        // Infer eventKey from teamData or use default
        const eventKey = (teamData.eventKey as string) || '2026txcle'; 
        const ourTeamKey = 'frc6377';

        const allReports = await loadEventReports(eventKey);
        const ourReports = allReports.filter(r => r.teamKey === ourTeamKey);
        const ourPit = await getPitReport(ourTeamKey, eventKey);

        if (ourReports.length > 0) {
            const TELE_TOWER: Record<string, number> = { Level1: 10, Level2: 20, Level3: 30, 'No Attempt': 0 };
            ourTeamData = {
                metrics: {
                    avgFuel: (ourReports.reduce((acc, r: ScoutReport) => acc + (r.data.auto?.fuel_scored || 0) + (r.data.teleop?.fuel_scored || 0), 0) / (ourReports.length || 1)).toFixed(1),
                    avgTowerPts: (ourReports.reduce((acc, r: ScoutReport) => acc + (TELE_TOWER[String(r.data.teleop?.climb_level)] || 0), 0) / (ourReports.length || 1)).toFixed(1),
                },
                pitReport: ourPit,
                synergyProfile: analyzeTeamRole(ourReports),
                defenseProfile: analyzeDefenseProfile(ourReports),
                matchNotes: ourReports.map((r: ScoutReport) => r.data.notes).filter((n): n is string => !!n)
            };
        }
    } catch (e) {
        console.error("[AI] Failed to fetch our team data for synergy:", e);
    }

    const { generateTeamQuestions } = await import('./ai');
    return await generateTeamQuestions(teamKey, { ...teamData, ourTeamData });
}

export async function getTacticalStrategy(matchKey: string, alliance: 'red' | 'blue', allianceData: Record<string, unknown>[], opponentData: Record<string, unknown>[]) {
    try {
        return await generateMatchStrategy(matchKey, alliance, allianceData, opponentData);
    } catch (e) {
        console.error('Tactical strategy error:', e);
        return 'Tactical link severed.';
    }
}

