import { OpenRouter } from "@openrouter/sdk";
import { getStatboticsEvent } from "./statbotics";

const client = new OpenRouter({
    apiKey: process.env.HACK_CLUB_AI_KEY || "",
    serverURL: "https://ai.hackclub.com/proxy/v1",
});

// 5-Minute Memory Cache Utility
const AI_CACHE = new Map<string, { content: string; expiry: number }>();
const CACHE_TTL = 1 * 60 * 60 * 1000; // 1 hour in ms

async function withCache(key: string, fn: () => Promise<string>): Promise<string> {
    const now = Date.now();
    const cached = AI_CACHE.get(key);
    if (cached && now < cached.expiry) {
        console.log(`[AI CACHE HIT] ${key}`);
        return cached.content;
    }

    console.log(`[AI GENERATING] Fetching new data for: ${key}...`);
    try {
        const result = await fn();
        console.log(`\n==================================================`);
        console.log(`[AI RESPONSE SUCCESS] ${key}`);
        console.log(`==================================================`);
        console.log(result);
        console.log(`==================================================\n`);

        if (result && !result.includes("severed") && !result.includes("offline")) {
            AI_CACHE.set(key, { content: result, expiry: now + CACHE_TTL });
        }
        return result;
    } catch (e) {
        console.error(`[AI EXCEPTION] Error generating for ${key}:`, e);
        throw e;
    }
}

const REBUILT_CONTEXT = `
The REBUILT 2026 game, presented by Haas, involves complex scoring systems and strategic "shifts" that dictate match flow. Based on the official game manual, here is an expanded ruleset and technical details to enhance your strategic overview:1. Autonomous Period (First 15 Seconds)Active Hubs: Both HUBS are active during AUTO.Fuel Scoring: FUEL scored in an active HUB earns 1 point per piece.Tower Advantage: If an ALLIANCE scores more FUEL than their opponents during AUTO, the opponent’s HUB becomes inactive for the duration of Shift 1 in Teleop.Tower Level 1: Robots can earn 15 points for reaching LEVEL 1 (off the carpet) during AUTO. A maximum of 2 ROBOTS per alliance can earn these points in this period.2. Teleop Period (2 Minutes 15 Seconds)The Shift System: The game features a "Hub Shift System" where HUBs alternate between active and inactive states in 25-second shifts.Active HUB: 1 point per FUEL piece.Inactive HUB: 0 points per FUEL piece.Throughput Scoring: A FUEL piece is officially scored once it passes through the top opening of the HUB and the sensor array. Scoring continues for 3 seconds after a HUB deactivates to account for processing time.Field Navigation:BUMP: A 6.5-inch barrier.TRENCH: A 22-inch clearance tunnel.AprilTags: These are used for localization and are placed on the HUB, TRENCHES, TOWER, and OUTPOST.3. Endgame (Final 30 Seconds)Endgame scoring (TOWER points) is assessed 3 seconds after the timer hits 0:00 or when all ROBOTS come to rest.Hub Status: Both HUBs return to active status for the final 30 seconds.Tower Levels:LEVEL 1 (10 Points): ROBOT is no longer touching the carpet or TOWER BASE.LEVEL 2 (20 Points): BUMPER covers must be completely above the LOW RUNG (approx. 27 inches).LEVEL 3 (30 Points): BUMPER covers must be completely above the MID RUNG (approx. 45 inches).Contact Rule: To earn TOWER points, a ROBOT must be contacting at least one RUNG or UPRIGHT on their TOWER.Tower Zone Protection: Initiating contact with an opponent inside their TOWER projection is a MAJOR FOUL. If the contact results in the opponent being awarded TOWER points, they receive the points for the LEVEL they were attempting (up to LEVEL 3).4. Violations and PenaltiesMinor Foul: 5 points added to the opponent's score.Major Foul: 15 points added to the opponent's score.G415 (Stay Out of Other Robots): Damaging an opponent inside their robot perimeter while your bumpers are outside your alliance zone results in a MAJOR FOUL and YELLOW CARD. If the opponent is disabled, it is a RED CARD.Ranking Points (RP)Energized RP (1 RP): Awarded if the alliance scores FUEL in an active HUB at or above a specific threshold.Supercharged RP (1 RP): Awarded for reaching a higher, secondary FUEL threshold.Traversal RP (1 RP): Earned when the alliance scores 50 or more total TOWER points.Match Performance:Win: 3 RP.Tie: 1 RP.
`;

