export interface PitReport {
    primaryKey: string;
    teamKey: string;        // frcXXXX
    eventKey: string;
    scoutedBy: string;
    // Physical
    weightLbs: number | null;
    heightIn: number | null;
    widthIn: number | null;
    lengthIn: number | null;
    // Drivetrain / Mechanism
    drivebase: string;
    codeLanguage: string;
    turret: string;
    climb: string;
    climbPosition1: string;
    climbPosition2: string;
    climbPartners: number;
    autoClimb: string;
    // Hopper / Fuel
    hopperCapacity: number | null;
    hopperLengthIn: number | null;
    hopperWidthIn: number | null;
    hopperHeightIn: number | null;
    // Field capabilities
    trench: string;
    bump: string;
    bumpPractice: string;
    canLob: string;
    canDoze: string;
    pickupFloor: string;
    pickupOutpost: string;
    // Auto preferences
    autoPrefStart: string;
